/* Banque de questions — partie 2 (même format que questions.js). */
window.THEMES.chargement = { nom: "Chargement, remorque & passagers", icon: "🧳" };

window.QUESTIONS.push(
  /* =================== VITESSE (suite) =================== */
  { id: "v18", t: "vitesse", q: "Vous dépassez ce panneau. Que change-t-il pour votre vitesse ?", s: "F3", o: ["Rien, la limite de 50 km/h continue jusqu'au prochain panneau", "Fin d'agglomération : la vitesse hors agglomération s'applique", "Début d'une zone 30 jusqu'à la sortie du village"], a: 1, e: "F3 (nom barré) : fin de l'agglomération. On reprend la vitesse hors agglomération de la Région (90 km/h en Wallonie, 70 km/h en Flandre), sauf panneau.", ref: "F3" },
  { id: "v19", t: "vitesse", q: "Sur autoroute, il pleut fortement. Aucun panneau particulier. La vitesse maximale légale est de :", o: ["120 km/h, mais je dois adapter ma vitesse aux conditions", "110 km/h automatiquement par temps de pluie", "90 km/h automatiquement dès que les essuie-glaces tournent"], a: 0, e: "En Belgique, il n'y a pas de limite « pluie » automatique (contrairement à la France). Mais l'obligation d'adapter sa vitesse (art. 10) impose de ralentir fortement si la visibilité ou l'adhérence diminuent.", p: "« 110 par temps de pluie », c'est la règle française.", ref: "Art. 10 / 11" },
  { id: "v20", t: "vitesse", g: true, q: "Un panneau à message variable au-dessus de l'autoroute affiche « 90 » dans un cercle rouge. Cette limitation :", o: ["Est obligatoire, comme un panneau fixe", "Est un simple conseil", "Ne concerne que les camions"], a: 0, e: "Les signaux à message variable ont la même valeur qu'un panneau classique. Un « 90 » dans un cercle rouge est une limitation obligatoire (souvent pour un bouchon, un accident ou de la pollution).", ref: "Signaux à message variable" },
  { id: "v21", t: "vitesse", q: "Vous roulez sous un panneau C43 « 50 ». Après un carrefour, il n'est pas répété. Que faites-vous ?", s: "C43_50", o: ["Je garde 50 km/h jusqu'à un panneau de fin de limitation", "Elle s'arrête au carrefour : la vitesse générale s'applique", "Je peux rouler à 70 km/h jusqu'au prochain panneau"], a: 1, e: "Une limitation de vitesse par C43 vaut jusqu'au prochain carrefour. Après, c'est la vitesse générale de l'endroit (50 en agglomération, 90/70 hors agglomération selon la Région…).", ref: "Art. 68.3" },
  { id: "v22", t: "vitesse", r: ["W"], q: "En Wallonie, hors agglomération, sur une route à 2 × 2 bandes SANS berme centrale (simple ligne au milieu), vitesse maximale sans panneau ?", o: ["90 km/h", "120 km/h", "70 km/h"], a: 0, fix: true, e: "La limite de 120 km/h hors autoroute exige une berme centrale (séparation physique). Sans elle, c'est la limite ordinaire : 90 km/h en Wallonie.", ref: "Art. 11.2" },
  { id: "v23", t: "vitesse", q: "Depuis le 1er juillet 2026, quel est le montant de la perception immédiate pour un excès de vitesse de 10 km/h au maximum ?", o: ["53 €", "58 €", "116 €"], a: 1, fix: true, e: "Depuis l'indexation de 10 % du 1er juillet 2026, un excès jusqu'à 10 km/h coûte 58 € (53 € avant). Au-delà, on ajoute un montant par km/h supplémentaire, plus élevé en agglomération, en zone 30 et aux abords d'écoles.", ref: "AR 2026 — police.be" },
  { id: "v24", t: "vitesse", q: "Un très gros excès (plus de 30 km/h en agglomération, plus de 40 km/h hors agglomération) peut-il se régler par une perception immédiate ?", o: ["Oui, toujours, quel que soit l'excès", "Non : le dossier part au parquet / tribunal", "Oui, si on paie sur place en liquide"], a: 1, e: "Au-delà de ces seuils, pas de perception immédiate : le parquet peut proposer une transaction ou citer devant le tribunal de police (amende plus lourde, déchéance possible).", ref: "Loi du 16 mars 1968" },
  { id: "v25", t: "vitesse", q: "Un « radar tronçon » contrôle :", o: ["Votre vitesse moyenne entre deux points", "Uniquement la vitesse au passage de la caméra", "La distance avec le véhicule devant"], a: 0, e: "Le contrôle de trajectoire (radar tronçon) calcule votre vitesse moyenne entre deux portiques. Freiner seulement sous les caméras ne sert à rien.", ref: "Contrôle de vitesse" },
  { id: "v26", t: "vitesse", q: "Par brouillard épais, vous ne voyez qu'à 50 m. Votre vitesse doit permettre :", o: ["De vous arrêter dans la distance que vous voyez libre", "De suivre les feux arrière du véhicule devant vous", "De respecter la vitesse maximale affichée"], a: 0, e: "Règle fondamentale : vous devez pouvoir vous arrêter devant un obstacle prévisible, donc dans la distance de visibilité. À 50 m de visibilité, c'est en pratique 40-50 km/h maximum.", p: "Suivre les feux arrière de quelqu'un donne une fausse impression de sécurité : s'il freine, vous le percutez.", ref: "Art. 10.1" },
  { id: "v27", t: "vitesse", q: "Sur route mouillée, la distance de freinage est, par rapport à une route sèche :", o: ["Identique, si les pneus sont en bon état", "Nettement plus longue (environ 1,5 à 2 fois)", "Plus courte, l'eau refroidissant les freins"], a: 1, e: "L'adhérence diminue sur route mouillée : comptez une distance de freinage environ 1,5 à 2 fois plus longue, et bien plus sur verglas (jusqu'à 10 fois).", ref: "Conduite défensive" },
  { id: "v28", t: "vitesse", q: "À l'approche d'un passage pour piétons, la loi impose de rouler :", o: ["À vitesse modérée", "À 20 km/h exactement", "Normalement si personne n'est visible"], a: 0, e: "On ne peut s'approcher d'un passage pour piétons qu'à vitesse modérée, de façon à pouvoir s'arrêter si un piéton s'y engage.", ref: "Art. 40.2" },
  { id: "v29", t: "vitesse", q: "Un panneau de fin de zone 30 (F4b). Vous êtes en agglomération en Wallonie. Nouvelle vitesse maximale ?", s: "F4b", o: ["30 km/h", "50 km/h", "70 km/h"], a: 1, fix: true, r: ["W", "F"], e: "En sortant d'une zone 30 en agglomération, la limite générale reprend : 50 km/h (en Wallonie et en Flandre).", ref: "F4b" },
  { id: "v30", t: "vitesse", q: "L'adaptation intelligente de la vitesse (ISA), obligatoire sur les voitures neuves depuis 2024 :", o: ["Vous avertit au-dessus de la limite ; désactivable temporairement", "Bride la voiture : il est impossible de dépasser la limite", "Remplace les panneaux : c'est la limite affichée qui fait foi"], a: 0, e: "L'ISA lit les panneaux / la cartographie et vous avertit (signal sonore, vibration, résistance de la pédale). Elle se réactive à chaque démarrage. Elle peut se tromper : la responsabilité reste la vôtre.", ref: "Règlement (UE) 2019/2144" },

  /* =================== PRIORITÉS (suite) =================== */
  { id: "p22", t: "priorite", g: true, q: "Carrefour sans signalisation. La rue de droite est étroite et pavée, la vôtre est large et asphaltée. Qui a la priorité ?", o: ["Moi, ma route est plus importante", "Celui qui vient de la rue de droite", "Le premier arrivé"], a: 1, e: "Sans signalisation, la priorité de droite s'applique quelle que soit la largeur, le revêtement ou l'importance apparente de la route. Seule exception : celui qui sort d'un chemin de terre ou d'un sentier.", p: "Une « grande » route sans B9 n'est PAS prioritaire.", ref: "Art. 12.3.1" },
  { id: "p23", t: "priorite", g: true, q: "Un tracteur débouche d'un chemin de terre situé à votre droite. Qui doit céder le passage ?", o: ["Moi : il vient de ma droite, je dois lui céder le passage", "Le tracteur : en sortant d'un chemin de terre, il cède", "Le plus lent des deux, pour ne pas freiner le trafic"], a: 1, e: "La priorité de droite ne profite pas à celui qui débouche d'un chemin de terre ou d'un sentier : il doit céder le passage.", ref: "Art. 12.3.1" },
  { id: "p24", t: "priorite", g: true, q: "Vous tournez à droite. Un cycliste roule tout droit sur la piste cyclable à votre droite. Qui passe en premier ?", o: ["Le cycliste", "Moi, je suis devant", "Moi, si j'ai mis mon clignotant"], a: 0, e: "En changeant de direction, vous devez céder le passage aux cyclistes qui circulent sur la piste cyclable (et aux piétons) que vous traversez. Regard dans le rétroviseur ET dans l'angle mort droit avant de tourner.", ref: "Art. 19.6" },
  { id: "p25", t: "priorite", q: "Un carrefour giratoire est signalé uniquement par le panneau D5, sans panneau B1. Qui a la priorité ?", s: "D5", o: ["Ceux qui sont déjà engagés sur l'anneau du rond-point", "Ceux qui entrent : la priorité de droite s'applique", "Personne : chacun passe à tour de rôle"], a: 1, e: "Le D5 seul impose le sens giratoire mais ne règle pas la priorité. Sans B1, la règle générale (priorité de droite) joue : ceux qui entrent viennent de la droite de ceux qui tournent. C'est rare mais ça existe !", p: "Le plus souvent, le D5 est combiné au B1 : alors priorité à ceux qui sont sur l'anneau.", ref: "Art. 12.3.1 / D5" },
  { id: "p26", t: "priorite", g: true, q: "Un agent lève le bras verticalement. Cela signifie :", o: ["Arrêt pour tous, sauf ceux déjà engagés dans le carrefour", "Passage libre pour tous ceux qui arrivent face à lui", "Ralentir et passer prudemment, sans obligation de s'arrêter"], a: 0, e: "Bras levé verticalement : « attention, arrêt » pour tous ceux qui approchent ; les conducteurs déjà engagés dans le carrefour doivent le dégager.", ref: "Art. 4.1" },
  { id: "p27", t: "priorite", q: "Le feu de votre carrefour est éteint (en panne). Un panneau B1 est placé sous le feu. Que faites-vous ?", s: "B1", o: ["J'applique le B1 : je cède le passage", "Priorité de droite", "Je passe, le feu ne m'arrête pas"], a: 0, e: "Les panneaux placés avec des feux s'appliquent quand les feux sont éteints ou à l'orange clignotant.", ref: "Art. 61 / B1" },
  { id: "p28", t: "priorite", q: "Un véhicule de police circule avec son feu bleu allumé mais SANS sirène. Est-il prioritaire ?", o: ["Oui, le feu bleu suffit à le rendre prioritaire", "Non : il faut le feu bleu ET la sirène", "Seulement la nuit, quand la sirène est interdite"], a: 1, e: "Les véhicules prioritaires ne bénéficient des dérogations (et vous ne devez leur céder le passage) que s'ils utilisent à la fois le feu bleu clignotant et l'avertisseur sonore spécial. Restez tout de même attentif.", ref: "Art. 37 / 38" },
  { id: "p29", t: "priorite", q: "Un piéton traverse la chaussée à 50 m de tout passage pour piétons. Qui a la priorité ?", o: ["Le piéton : il est toujours prioritaire, où qu'il traverse", "Le piéton doit céder, mais vous ne devez pas le mettre en danger", "Vous : vous pouvez klaxonner et passer sans ralentir"], a: 1, e: "Hors passage, le piéton doit traverser prudemment en tenant compte des véhicules (il doit utiliser un passage s'il y en a un à moins de 20 m). Mais le conducteur reste tenu à une prudence particulière envers lui (usager vulnérable).", ref: "Code de la route : piétons" },
  { id: "p30", t: "priorite", g: true, q: "Vous sortez de votre garage en marche arrière. Un piéton marche sur le trottoir. Qui passe ?", o: ["Le piéton", "Moi, je suis chez moi", "Le premier qui klaxonne"], a: 0, e: "Sortir d'une propriété et faire marche arrière sont deux manœuvres : vous cédez le passage à tous, y compris aux piétons sur le trottoir.", ref: "Art. 12.4" },
  { id: "p31", t: "priorite", g: true, q: "Vous voulez passer de la bande de droite à celle de gauche. Une voiture arrive dans la bande de gauche. Qui a la priorité ?", o: ["La voiture dans la bande de gauche", "Moi, avec le clignotant", "Celui qui roule le plus vite"], a: 0, e: "Changer de bande est une manœuvre : vous cédez le passage aux usagers qui circulent déjà dans la bande visée.", ref: "Art. 12.4" },
  { id: "p32", t: "priorite", q: "Un cortège funèbre ou un groupe d'enfants en rang encadré traverse. Vous pouvez :", o: ["Le couper rapidement s'il reste un espace", "Non : interdit de couper un cortège, j'attends", "Klaxonner pour qu'ils laissent un passage"], a: 1, e: "Il est interdit de couper un cortège (militaire, funèbre, groupe encadré de piétons ou de cyclistes). Attendez qu'il soit passé.", ref: "Code de la route" },
  { id: "p33", t: "priorite", q: "Face à un panneau B1 et une ligne de dents de requin, êtes-vous obligé de vous arrêter ?", s: "B1", o: ["Oui, toujours, exactement comme au STOP", "Non : seulement si c'est nécessaire pour céder", "Oui, mais seulement la nuit ou par mauvaise visibilité"], a: 1, e: "Le B1 oblige à céder le passage, pas à s'arrêter systématiquement (contrairement au STOP). Si la voie est libre, vous pouvez continuer prudemment.", ref: "B1" },
  { id: "p34", t: "priorite", g: true, q: "Vous êtes sur une route prioritaire (B9) et vous tournez à gauche. Une voiture arrive en face, sur la même route prioritaire, et va tout droit. Qui passe ?", s: "B9", o: ["Moi, je suis sur la route prioritaire", "La voiture d'en face", "Celui qui arrive le premier"], a: 1, e: "Être sur une route prioritaire vous donne la priorité sur les routes latérales, pas sur ceux qui viennent en face sur la même route : en tournant à gauche, vous leur cédez le passage.", ref: "Art. 19.5" },
  { id: "p35", t: "priorite", g: true, q: "À un passage à niveau sans barrières ni feux, un train approche. Qui a la priorité ?", s: "A43", o: ["Le train, toujours", "Moi si je suis déjà proche", "Celui qui vient de droite"], a: 0, e: "Le train a toujours la priorité. Il ne peut ni dévier ni s'arrêter sur une courte distance (souvent plus de 800 m à 100 km/h).", ref: "Art. 34" },
  { id: "p36", t: "priorite", q: "Vous quittez une place de stationnement pour vous insérer dans la circulation. Un cycliste arrive derrière vous. Vous :", o: ["Le laissez passer avant de démarrer", "Démarrez avec le clignotant, il freinera", "Klaxonnez"], a: 0, e: "Démarrer est une manœuvre : vous cédez le passage à tous les usagers, cyclistes compris. Regardez dans le rétroviseur et par-dessus l'épaule (angle mort).", ref: "Art. 12.4" },
  { id: "p37", t: "priorite", g: true, q: "Ce panneau est placé sur votre route avant un carrefour. Au carrefour SUIVANT celui-là, sans autre panneau :", s: "B15", o: ["J'ai toujours la priorité jusqu'au panneau de fin", "La priorité de droite s'applique de nouveau", "Je dois m'arrêter à chaque carrefour suivant"], a: 1, e: "Le B15 ne vaut que pour le prochain carrefour. Au-delà, sauf nouveau panneau, c'est la priorité de droite.", ref: "B15" },
  { id: "p38", t: "priorite", q: "Un feu vert pour vous, mais un véhicule prioritaire (feu bleu + sirène) arrive par la droite. Vous :", o: ["Passez : j'ai le vert", "Le laissez passer", "Accélérez pour dégager"], a: 1, e: "Un véhicule prioritaire en intervention peut franchir un feu rouge. Même au vert, vous devez lui céder le passage.", ref: "Art. 38" },

  /* =================== PANNEAUX (suite) =================== */
  { id: "s23", t: "panneaux", q: "Que signifie ce panneau ?", s: "A17", o: ["Projection de gravillons", "Route en mauvais état", "Chantier"], a: 0, e: "A17 : gravillons pouvant être projetés. Ralentissez et augmentez la distance avec le véhicule devant.", ref: "A17" },
  { id: "s24", t: "panneaux", q: "Que signifie ce panneau ?", s: "A19", o: ["Chute de pierres", "Passage d'animaux", "Éboulement interdit"], a: 0, e: "A19 : risque de chute de pierres. Ralentissez, surtout après la pluie ou le dégel.", ref: "A19" },
  { id: "s25", t: "panneaux", q: "Ce panneau annonce :", s: "A37", o: ["Du vent latéral", "Un aéroport", "Un drapeau de chantier"], a: 0, e: "A37 : vent latéral (viaduc, sortie de bois…). Tenez fermement le volant, surtout en dépassant un camion.", ref: "A37" },
  { id: "s26", t: "panneaux", q: "Ce panneau signale :", s: "A49", o: ["Une traversée de tram", "Un arrêt de bus", "Une gare"], a: 0, e: "A49 : endroit où un tram traverse la chaussée. Rappel : le tram a la priorité (sauf signalisation contraire).", ref: "A49" },
  { id: "s27", t: "panneaux", q: "Ce panneau est placé sous un feu rouge. Vous êtes en voiture et voulez tourner à droite. Pouvez-vous passer au rouge ?", s: "B22", o: ["Oui, en cédant le passage aux autres usagers", "Non : il ne concerne que les cyclistes (et assimilés)", "Oui, mais seulement la nuit quand c'est calme"], a: 1, e: "Le B22 (vélo + flèche orange) autorise seulement les cyclistes à tourner à droite au rouge, en cédant le passage. Pour les voitures, le rouge reste le rouge.", ref: "B22" },
  { id: "s28", t: "panneaux", q: "Que signifie ce panneau placé sous un feu ?", s: "B23", o: ["Les cyclistes peuvent continuer tout droit au rouge, en cédant", "Une piste cyclable obligatoire commence après le carrefour", "Les cyclistes doivent mettre pied à terre au feu rouge"], a: 0, e: "B23 : les cyclistes peuvent franchir le feu rouge pour aller tout droit, en cédant le passage aux autres usagers.", ref: "B23" },
  { id: "s29", t: "panneaux", q: "Ce panneau interdit l'accès :", s: "C5", o: ["Aux véhicules à moteur à plus de deux roues et aux side-cars", "Aux véhicules garés plus de 2 heures dans la même rue", "Aux taxis et aux voitures de location uniquement"], a: 0, e: "C5 : accès interdit aux conducteurs de véhicules automobiles à plus de deux roues et de motocyclettes avec side-car. Les motos « solo » et les vélos peuvent passer.", ref: "C5" },
  { id: "s30", t: "panneaux", q: "Votre voiture a une masse maximale autorisée de 1 900 kg. Pouvez-vous passer sous ce panneau ?", s: "C21", o: ["Oui, ma masse en charge est inférieure à 3,5 t", "Non, il interdit toutes les voitures particulières", "Seulement si la voiture roule à vide"], a: 0, e: "C21 : interdit aux véhicules dont la masse en charge dépasse le chiffre indiqué. Avec une voiture de moins de 3,5 t, vous pouvez passer.", ref: "C21" },
  { id: "s31", t: "panneaux", q: "Ce panneau interdit l'accès :", s: "C23", o: ["Aux véhicules de transport de choses", "Aux bus et autocars de plus de 3,5 t", "À tous les véhicules à moteur"], a: 0, e: "C23 : accès interdit aux conducteurs de véhicules affectés au transport de choses (souvent complété par une masse, ex. « + 3,5 t »).", ref: "C23" },
  { id: "s32", t: "panneaux", q: "Que signifie ce panneau ?", s: "C29", o: ["Hauteur maximale (chargement compris)", "Longueur maximale (remorque comprise)", "Altitude de la route au-dessus de la mer"], a: 0, e: "C29 : accès interdit aux véhicules dont la hauteur, chargement compris, dépasse le chiffre indiqué. Attention avec un coffre de toit, des vélos sur le toit ou une camionnette de location !", ref: "C29" },
  { id: "s33", t: "panneaux", q: "Que signifie ce panneau ?", s: "C27", o: ["Largeur maximale", "Distance minimale entre véhicules", "Parking de 2,3 m"], a: 0, e: "C27 : interdit aux véhicules (chargement compris) plus larges que la valeur indiquée.", ref: "C27" },
  { id: "s34", t: "panneaux", q: "Ce panneau vous concerne-t-il si vous conduisez une voiture ?", s: "C39", o: ["Non : il vise les camions de plus de 3,5 t", "Oui : dépassement interdit à tous les véhicules", "Oui, mais seulement la nuit"], a: 0, e: "C39 : dépassement interdit aux véhicules de transport de choses de plus de 3,5 t. Les voitures peuvent dépasser (si rien d'autre ne l'interdit).", ref: "C39" },
  { id: "s35", t: "panneaux", q: "Ce panneau signifie :", s: "D11", o: ["Chemin obligatoire pour piétons", "Passage pour piétons", "Accès interdit aux piétons"], a: 0, e: "Rond bleu = obligation. D11 : partie de la voie publique réservée aux piétons, qui sont tenus de l'emprunter.", ref: "D11" },
  { id: "s36", t: "panneaux", q: "Vous passez ce panneau en sortant d'une zone. Que devez-vous faire au carrefour qui suit ?", s: "F12b", o: ["Céder le passage à tous les usagers", "J'ai la priorité car je viens d'une zone protégée", "Continuer à 20 km/h jusqu'au carrefour"], a: 0, e: "F12b : fin de zone résidentielle / de rencontre. En la quittant, vous cédez le passage à tous les autres usagers.", ref: "F12b / art. 12.4" },
  { id: "s37", t: "panneaux", q: "Ce panneau indique :", s: "F17", o: ["Une bande réservée aux bus", "Un arrêt de bus", "Un parking pour bus"], a: 0, e: "F17 : bande réservée aux bus (et aux usagers éventuellement autorisés par un panneau additionnel). Vous ne pouvez pas y rouler.", ref: "F17" },
  { id: "s38", t: "panneaux", q: "Après ce panneau, pouvez-vous à nouveau dépasser les cyclistes (en respectant la distance latérale) ?", s: "F113", o: ["Oui, c'est la fin de la rue cyclable", "Non, jamais en agglomération", "Seulement à 20 km/h maximum"], a: 0, e: "F113 : fin de rue cyclable. Le dépassement des cyclistes redevient possible (1 m en agglomération, 1,5 m hors agglomération) et la vitesse de l'endroit s'applique.", ref: "F113" },
  { id: "s39", t: "panneaux", q: "Que signifie ce panneau ?", s: "A1b", o: ["Virage dangereux à droite", "Obligation de tourner à droite", "Route sinueuse"], a: 0, e: "A1b : virage dangereux vers la droite. Le triangle = danger ; une obligation serait un rond bleu.", ref: "A1b" },
  { id: "s40", t: "panneaux", q: "Ce panneau annonce :", s: "A7a", o: ["Une chaussée rétrécie", "Un pont", "Une voie sans issue"], a: 0, e: "A7a : chaussée rétrécie (des deux côtés). Ralentissez et restez à droite.", ref: "A7a" },
  { id: "s41", t: "panneaux", q: "Ce panneau annonce :", s: "A14", o: ["Un dos d'âne ou ralentisseur", "Une forte montée", "Une chaussée déformée"], a: 0, e: "A14 : dos d'âne / ralentisseur. Ralentir pour ne pas abîmer le véhicule ni perdre le contrôle.", ref: "A14" },
  { id: "s42", t: "panneaux", q: "Ce panneau signale :", s: "A25", o: ["Un endroit où des cyclistes peuvent traverser", "Une piste cyclable obligatoire pour les vélos", "Une interdiction d'accès aux cyclistes"], a: 0, e: "A25 (triangle) : danger, passage de cyclistes. D7 (rond bleu) : piste obligatoire. C11 (rond rouge) : interdit aux cyclistes.", ref: "A25" },
  { id: "s43", t: "panneaux", q: "Ce panneau signale :", s: "A31", o: ["Des travaux", "Un jardinier", "Un camping"], a: 0, e: "A31 : travaux. Ralentissez, des ouvriers ou des engins peuvent se trouver sur la chaussée. Les marquages jaunes temporaires priment alors sur les blancs.", ref: "A31" },
  { id: "s44", t: "panneaux", q: "Ce panneau annonce :", s: "A33", o: ["Des signaux lumineux", "Un passage à niveau", "Une zone éclairée"], a: 0, e: "A33 : feux de signalisation (souvent masqués par un virage ou une côte).", ref: "A33" },
  { id: "s45", t: "panneaux", q: "Ce panneau annonce :", s: "A41", o: ["Un passage à niveau avec barrières", "Un passage à niveau sans barrières", "Une clôture"], a: 0, e: "A41 : passage à niveau muni de barrières ou de demi-barrières.", ref: "A41" },
  { id: "s46", t: "panneaux", q: "Ce panneau interdit l'accès :", s: "C11", o: ["Aux cyclistes", "Aux motos", "Aux vélos à moteur uniquement"], a: 0, e: "C11 : accès interdit aux cyclistes.", ref: "C11" },
  { id: "s47", t: "panneaux", q: "Ce panneau interdit l'accès :", s: "C19", o: ["Aux piétons", "Aux enfants", "Aux joggeurs uniquement"], a: 0, e: "C19 : accès interdit aux piétons.", ref: "C19" },
  { id: "s48", t: "panneaux", q: "Ce panneau vous interdit :", s: "C31b", o: ["De tourner à droite", "D'aller tout droit", "De faire demi-tour"], a: 0, e: "C31b : interdiction de tourner à droite au prochain carrefour.", ref: "C31" },
  { id: "s49", t: "panneaux", q: "Que signifie ce panneau ?", s: "C37", o: ["Fin de l'interdiction de dépasser", "Dépassement interdit", "Fin de route prioritaire"], a: 0, e: "C37 : fin de l'interdiction de dépasser imposée par un C35.", ref: "C37" },
  { id: "s50", t: "panneaux", q: "Que signifie ce panneau ?", s: "D1r", o: ["Obligation de tourner à droite", "Interdiction de tourner à droite", "Virage à droite"], a: 0, e: "Rond bleu + flèche : direction obligatoire. Ici, vous devez prendre à droite.", ref: "D1" },
  { id: "s51", t: "panneaux", q: "Que signifie ce panneau ?", s: "D9", o: ["Chemin réservé aux piétons et aux cyclistes", "Zone piétonne où les vélos sont tolérés", "Piste cyclable conseillée, voitures admises"], a: 0, e: "D9 : partie de la voie publique réservée aux piétons et aux cyclistes, qui doivent l'emprunter (séparés si une ligne les sépare).", ref: "D9" },
  { id: "s52", t: "panneaux", q: "Ce panneau autorise :", s: "E9a", o: ["Le stationnement", "L'arrêt uniquement", "Le stationnement réservé aux bus"], a: 0, e: "E9a : parking, stationnement autorisé (un panneau additionnel peut restreindre : catégorie, durée, disque, payant…).", ref: "E9a" },
  { id: "s53", t: "panneaux", q: "Ce panneau indique :", s: "F49", o: ["Un passage pour piétons", "Une zone piétonne", "Un danger : piétons"], a: 0, e: "F49 (carré bleu) : localisation d'un passage pour piétons. Le A21 (triangle) l'annonce comme danger, plus loin.", ref: "F49" },
  { id: "s54", t: "panneaux", q: "Ce panneau indique :", s: "F87", o: ["Un ralentisseur de trafic", "L'entrée d'un tunnel", "Un pont à une seule voie"], a: 0, e: "F87 : ralentisseur de trafic (dispositif surélevé).", ref: "F87" },
  { id: "s55", t: "panneaux", q: "Ce panneau marque :", s: "F7", o: ["La fin de l'autoroute", "Une autoroute fermée", "Un pont interdit"], a: 0, e: "F7 : fin de l'autoroute. Les règles générales (et les limites de vitesse ordinaires) reprennent.", ref: "F7" },
  { id: "s56", t: "panneaux", q: "Ce panneau marque :", s: "F104", o: ["La fin d'une zone piétonne", "Une interdiction aux piétons", "Un passage pour piétons supprimé"], a: 0, e: "F104 : fin de zone piétonne.", ref: "F104" },
  { id: "s57", t: "panneaux", q: "Ce panneau signifie :", s: "C43_120", o: ["Vitesse maximale 120 km/h", "Vitesse minimale 120 km/h", "Vitesse conseillée"], a: 0, e: "Cercle rouge = maximum obligatoire. Une vitesse minimale serait indiquée sur un rond bleu (D).", ref: "C43" },
  { id: "s58", t: "panneaux", q: "Les panneaux rectangulaires blancs placés sous un panneau principal sont :", o: ["Des panneaux additionnels (distance, durée, exceptions)", "Des panneaux d'information touristique ou commerciale", "Des conseils de prudence sans valeur obligatoire"], a: 0, e: "Ils précisent la portée du panneau principal : « sauf riverains », « 150 m », flèche de début/fin, silhouette de véhicule…", ref: "Art. 65" },
  { id: "s59", t: "panneaux", q: "Un panneau de danger porte un panneau additionnel « 300 m ». Le danger est :", o: ["À 300 m", "Sur 300 m de long", "Interdit sur 300 m"], a: 0, e: "Un chiffre seul indique la distance jusqu'au danger. Une longueur (« sur 2 km ») ou des flèches verticales indiquent l'étendue.", ref: "Art. 65" },
  { id: "s60", t: "panneaux", q: "Quelle est la forme du panneau STOP ?", o: ["Octogone rouge", "Triangle pointe en bas", "Rond rouge"], a: 0, e: "Octogone rouge : STOP (B5). Sa forme unique le rend reconnaissable même de dos ou couvert de neige.", ref: "B5" },

  /* =================== FEUX, AGENTS, MARQUAGES (suite) =================== */
  { id: "f15", t: "feux", g: true, q: "Le feu passe au rouge alors que vous êtes déjà au milieu du carrefour (engagé régulièrement). Vous :", o: ["Dégagez le carrefour", "Restez arrêté au milieu", "Reculez"], a: 0, e: "Un conducteur engagé régulièrement dans le carrefour doit le dégager sans tarder, en faisant attention aux autres.", ref: "Art. 61.1" },
  { id: "f16", t: "feux", q: "Des feux rouges clignotant alternativement sont placés à la sortie d'une caserne de pompiers. Vous :", o: ["Vous arrêtez", "Ralentissez simplement", "Passez si personne ne sort"], a: 0, e: "Feux rouges clignotants alternatifs (passage à niveau, pont mobile, sortie de pompiers/ambulances, piste d'aviation) : arrêt obligatoire.", ref: "Art. 61.2" },
  { id: "f17", t: "feux", q: "Un feu affiche une barre blanche horizontale. Il s'adresse :", o: ["Aux bus et trams (signaux spéciaux)", "À tous les conducteurs de la bande", "Aux piétons qui traversent"], a: 0, e: "Les signaux à barres ou points blancs sont réservés aux véhicules des transports en commun. Les voitures suivent leur propre feu.", ref: "Art. 62" },
  { id: "f18", t: "feux", q: "Une ligne continue est doublée d'une ligne discontinue de VOTRE côté. Pouvez-vous la franchir pour dépasser ?", o: ["Oui, depuis mon côté (discontinu), si c'est sûr", "Non, une ligne continue interdit tout franchissement", "Oui, dans les deux sens, si personne n'arrive"], a: 0, e: "Ligne mixte : on suit la ligne qui est de son côté. Discontinue de votre côté → franchissable ; continue de votre côté → interdit.", ref: "Art. 72.3" },
  { id: "f19", t: "feux", q: "Des flèches blanches obliques peintes sur la chaussée (« flèches de rabattement ») annoncent :", o: ["Une ligne continue ou la fin d'une bande : se rabattre", "Une sortie d'autoroute à prendre obligatoirement", "Une zone de stationnement sur la droite"], a: 0, e: "Les flèches de rabattement indiquent qu'il faut regagner la bande indiquée (ligne continue qui commence, bande qui se termine).", ref: "Art. 77.1" },
  { id: "f20", t: "feux", q: "Une ligne jaune en zigzag le long du bord signifie :", o: ["Stationnement interdit (ex. arrêt de bus)", "Piste cyclable temporaire", "Ralentisseur à l'approche d'une école"], a: 0, e: "Ligne jaune en zigzag : stationnement interdit sur la longueur marquée (souvent à un arrêt de bus).", ref: "Marquages : bord de chaussée" },
  { id: "f21", t: "feux", q: "Une zone à rayures blanches (zone d'évitement) délimitée par une ligne continue :", o: ["Interdite : on ne peut ni y circuler ni s'y arrêter", "Autorisée pour dépasser si la voie est libre", "Utilisable comme zone d'arrêt de courte durée"], a: 0, e: "Une zone d'évitement délimitée par une ligne continue ne peut pas être empruntée. Elle sépare les flux ou protège un îlot.", ref: "Marquages : zone d'évitement" },
  { id: "f22", t: "feux", q: "Des marquages de vélos et de chevrons sur la chaussée, sans ligne de délimitation, forment une « bande cyclable suggérée ». Pour un automobiliste :", o: ["Pas de valeur obligatoire : on peut y rouler, prudemment", "Interdit d'y rouler, comme sur une vraie piste cyclable", "Une piste cyclable obligatoire pour les vélos uniquement"], a: 0, e: "La bande cyclable suggérée n'est pas une piste cyclable : elle attire l'attention sur la présence de cyclistes, sans réserver l'espace.", ref: "Marquage de suggestion" },
  { id: "f23", t: "feux", g: true, q: "Au feu rouge, une zone avancée pour cyclistes (« sas vélo ») est peinte devant la ligne. Où vous arrêtez-vous ?", o: ["Avant la première ligne d'arrêt, derrière le sas", "Dans le sas, juste derrière la seconde ligne", "Peu importe"], a: 0, e: "Le sas vélo est réservé aux cyclistes (et cyclomotoristes 2 roues). Les autres véhicules s'arrêtent avant la première ligne.", ref: "Marquages : zone avancée pour cyclistes" },
  { id: "f24", t: "feux", q: "Une flèche de sélection blanche (tout droit) est peinte dans votre bande à l'approche d'un carrefour. Pouvez-vous tourner à gauche depuis cette bande ?", o: ["Non : je dois suivre la direction indiquée", "Oui, en mettant mon clignotant à temps", "Oui, s'il n'y a personne dans la bande de gauche"], a: 0, e: "Les flèches de sélection sont obligatoires : vous suivez la direction de la flèche de votre bande. Choisissez votre bande à temps.", ref: "Art. 77.1" },
  { id: "f25", t: "feux", q: "Sur un chantier, des lignes JAUNES sont peintes par-dessus les lignes blanches. Lesquelles suivez-vous ?", o: ["Les jaunes (marquages temporaires)", "Les blanches (marquages permanents)", "Les deux, en choisissant la plus prudente"], a: 0, e: "Les marquages jaunes temporaires (chantiers, déviations) priment sur les marquages blancs permanents.", ref: "Art. 72" },
  { id: "f26", t: "feux", q: "Une personne chargée de la surveillance d'un passage scolaire tient un panneau « STOP ». Vous :", o: ["Vous arrêtez", "Ralentissez seulement", "Passez si les enfants ne sont pas encore sur la chaussée"], a: 0, e: "Les surveillants habilités (gardiens de passage, patrouilleurs scolaires) peuvent arrêter la circulation : il faut obéir.", ref: "Art. 5" },
  { id: "f27", t: "feux", q: "Une ligne blanche continue transversale (ligne d'arrêt) est tracée au carrefour, sans feu ni panneau STOP visible. Elle indique :", o: ["L'endroit où s'arrêter si un arrêt est imposé", "Un passage pour piétons non signalé", "La fin d'une zone de stationnement"], a: 0, e: "La ligne d'arrêt continue marque où s'arrêter quand un signal l'impose. Une ligne de triangles = cédez le passage.", ref: "Art. 76.2" },

  /* =================== CROISEMENT & DÉPASSEMENT (suite) =================== */
  { id: "d12", t: "depassement", q: "Sur autoroute, bouchon : la file de droite avance plus vite que la vôtre à gauche. Est-ce un dépassement interdit par la droite ?", o: ["Non : en files denses, une file plus rapide n'est pas un dépassement", "Oui, c'est toujours un dépassement interdit par la droite", "Oui, sauf la nuit quand le trafic est fluide"], a: 0, e: "Quand la circulation est dense et forme des files, le fait qu'une file avance plus vite qu'une autre n'est pas un dépassement interdit. Par contre, changer de file pour « doubler » par la droite reste interdit.", ref: "Art. 17.1" },
  { id: "d13", t: "depassement", g: true, q: "Est-il permis de dépasser à un carrefour ?", o: ["En principe non, sauf exceptions (route prioritaire, feux…)", "Oui, toujours, si la visibilité est bonne dans le carrefour", "Oui, à condition de prévenir avec l'avertisseur sonore"], a: 0, e: "Le dépassement est interdit à l'approche des carrefours et dans les carrefours, sauf si vous êtes sur une route prioritaire, si le carrefour est réglé par feux/agent, si c'est un giratoire, pour dépasser un deux-roues, ou pour dépasser par la droite un véhicule qui tourne à gauche.", ref: "Art. 17.2.3" },
  { id: "d14", t: "depassement", g: true, q: "À l'approche d'un passage à niveau sans barrières, pouvez-vous dépasser ?", s: "A43", o: ["Non", "Oui si le train n'est pas visible", "Oui à vitesse réduite"], a: 0, e: "Il est interdit de dépasser à l'approche et sur un passage à niveau (sans barrières). Une immobilisation imprévue sur les voies serait fatale.", ref: "Art. 17.2" },
  { id: "d15", t: "depassement", g: true, q: "Sous ce panneau, un tracteur agricole roule à 25 km/h devant vous. Pouvez-vous le dépasser ?", s: "C35", o: ["Non : il a plus de deux roues", "Oui : c'est un véhicule lent", "Oui, s'il me fait signe"], a: 0, e: "Le C35 interdit de dépasser tout véhicule à plus de deux roues, même lent (tracteur, voiturette). Seuls les deux-roues peuvent être dépassés.", p: "« Il roule lentement » n'est pas une exception légale.", ref: "C35" },
  { id: "d16", t: "depassement", q: "Après avoir dépassé, quand pouvez-vous vous rabattre ?", o: ["Quand je le vois dans mon rétroviseur intérieur, sans le gêner", "Dès que mon pare-chocs avant a dépassé le sien", "Immédiatement après l'avoir dépassé, pour libérer la voie"], a: 0, e: "On se rabat sans obliger le véhicule dépassé à freiner : un bon repère est de le voir entièrement dans le rétroviseur intérieur. On signale avec le clignotant droit.", ref: "Art. 16.4" },
  { id: "d17", t: "depassement", q: "Hors agglomération, de jour, peut-on utiliser l'avertisseur sonore pour annoncer un dépassement ?", o: ["Oui, si nécessaire", "Non, jamais", "Seulement sur autoroute"], a: 0, e: "Hors agglomération, l'avertisseur sonore peut servir à prévenir un conducteur que vous allez le dépasser. La nuit, on préfère de brefs appels de phares.", ref: "Art. 33" },
  { id: "d18", t: "depassement", q: "Un bus est arrêté à un arrêt, des passagers descendent. Vous le dépassez :", o: ["Lentement, prêt à m'arrêter : un piéton peut surgir", "Rapidement, pour libérer la voie au bus", "En klaxonnant pour prévenir les passagers"], a: 0, e: "Les passagers qui descendent traversent souvent devant ou derrière le bus. Ralentir et anticiper.", ref: "Perception des risques" },
  { id: "d19", t: "depassement", q: "Vous croisez un véhicule large sur une route étroite. Le bon comportement est :", o: ["Ralentir, serrer à droite et au besoin s'arrêter", "Garder ma vitesse en restant au centre", "Faire des appels de phares pour qu'il recule"], a: 0, e: "Pour croiser, chacun serre à droite et ralentit. Si nécessaire, arrêtez-vous à un endroit plus large.", ref: "Art. 15" },
  { id: "d20", t: "depassement", q: "En zone 30, un cycliste roule à 25 km/h devant vous dans une rue étroite. Vous :", o: ["Restez derrière s'il est impossible de laisser 1 m", "Le dépassez en lui laissant 50 cm", "Klaxonnez pour qu'il monte sur le trottoir"], a: 0, e: "Si la distance latérale minimale (1 m en agglomération) n'est pas possible, on ne dépasse pas. À 30 km/h, l'écart de vitesse est faible : patience.", ref: "Art. 40ter" },
  { id: "d21", t: "depassement", q: "Une voiture devant vous a mis son clignotant gauche pour dépasser. Vous aviez aussi prévu de dépasser. Vous :", o: ["Attendez : il a signalé le premier", "Le dépassez d'abord", "Dépassez les deux en même temps"], a: 0, e: "Avant de dépasser, vous devez vérifier que le conducteur devant n'a pas annoncé son intention de dépasser. Il a la priorité de manœuvre.", ref: "Art. 16.4" },
  { id: "d22", t: "depassement", g: true, q: "Une ligne blanche continue sépare les deux sens. Un cycliste lent roule devant vous. Pouvez-vous chevaucher la ligne pour le dépasser ?", o: ["Non : franchir ou chevaucher une ligne continue est interdit", "Oui : pour dépasser un cycliste, c'est toujours autorisé", "Oui, si personne n'arrive en face et que la visibilité est bonne"], a: 0, e: "En Belgique, la ligne continue ne peut être ni franchie ni chevauchée. Si vous ne pouvez pas dépasser en laissant la distance latérale sans toucher la ligne, vous restez derrière.", p: "En France une tolérance existe pour dépasser les cyclistes ; pas dans le code belge actuel.", ref: "Art. 72.2" },

  /* =================== ARRÊT & STATIONNEMENT (suite) =================== */
  { id: "st12", t: "stationnement", q: "Hors agglomération, où devez-vous de préférence vous arrêter ou stationner ?", o: ["Sur l'accotement de plain-pied, sinon le plus à droite possible", "Au milieu de la chaussée, avec les feux de détresse", "Sur la piste cyclable si elle est libre"], a: 0, e: "Hors agglomération, on utilise l'accotement de plain-pied (au même niveau que la chaussée) ; sinon, la chaussée en restant à droite.", ref: "Art. 23.1" },
  { id: "st13", t: "stationnement", g: true, q: "Le stationnement en double file pour « deux minutes » avec les feux de détresse est :", o: ["Interdit", "Permis avec les feux de détresse", "Permis en agglomération"], a: 0, e: "Le stationnement en double file est interdit. Les feux de détresse n'y changent rien.", ref: "Art. 24 / 31" },
  { id: "st14", t: "stationnement", q: "Dans une rue à double sens, pouvez-vous stationner à gauche (dans le sens contraire à votre marche) ?", o: ["Non : on stationne à droite par rapport à son sens", "Oui, partout où il reste assez de place", "Oui, mais seulement la nuit ou le dimanche"], a: 0, e: "Dans une rue à double sens, on s'arrête et on stationne du côté droit. Seule une rue à sens unique permet les deux côtés.", ref: "Art. 23.1" },
  { id: "st15", t: "stationnement", g: true, q: "Une place est réservée aux personnes handicapées. Vous n'avez pas de carte de stationnement. Pouvez-vous y stationner « juste 5 minutes » ?", o: ["Non, jamais", "Oui, 5 minutes", "Oui, avec les feux de détresse"], a: 0, e: "Les emplacements réservés aux personnes handicapées ne peuvent être utilisés qu'avec la carte spéciale apposée visiblement. Infraction lourdement sanctionnée.", ref: "Stationnement réservé (carte spéciale)" },
  { id: "st16", t: "stationnement", q: "Peut-on s'arrêter sur une ligne jaune continue tracée le long du bord pour déposer un passager ?", o: ["Non : arrêt et stationnement interdits", "Oui, l'arrêt reste permis, pas le stationnement", "Oui, avec les feux de détresse allumés"], a: 0, e: "Ligne jaune continue = arrêt ET stationnement interdits (comme le E3).", ref: "Marquages : bord de chaussée" },
  { id: "st17", t: "stationnement", q: "Peut-on stationner sur une bande réservée aux bus ?", o: ["Non", "Oui le dimanche", "Oui en dehors des heures de pointe, sans panneau"], a: 0, e: "Arrêt et stationnement interdits sur les bandes bus (sauf indication contraire d'un panneau additionnel horaire).", ref: "Art. 24" },
  { id: "st18", t: "stationnement", q: "Avant de quitter votre véhicule stationné, vous devez notamment :", o: ["Couper le moteur, serrer le frein et s'assurer qu'il ne peut pas bouger", "Laisser le moteur tourner pour garder le chauffage allumé", "Laisser la clé sur le contact pour pouvoir le déplacer"], a: 0, e: "Le conducteur ne peut s'éloigner sans avoir pris les précautions pour éviter tout accident (frein, rapport engagé ou position P, roues braquées en pente) et pour empêcher l'usage du véhicule sans autorisation.", ref: "Code de la route : précautions au stationnement" },
  { id: "st19", t: "stationnement", q: "En pente descendante, le long d'un trottoir, comment braquer les roues avant au stationnement ?", o: ["Vers le trottoir", "Vers la chaussée", "Droites"], a: 0, e: "En descente, roues braquées vers le trottoir : si le frein lâche, la roue bute contre la bordure. En montée (avec bordure), roues vers la chaussée.", ref: "Bonne pratique" },
  { id: "st20", t: "stationnement", q: "Un emplacement avec un panneau P et un symbole de prise électrique est en principe réservé :", o: ["Aux véhicules électriques en recharge", "À tous les véhicules, sans condition", "Aux taxis et aux voitures partagées"], a: 0, e: "Les emplacements de recharge sont réservés aux véhicules électriques qui rechargent (un panneau additionnel précise les conditions et parfois une durée maximale).", ref: "E9a + additionnel" },
  { id: "st21", t: "stationnement", q: "Le disque de stationnement doit indiquer :", o: ["L'heure d'arrivée (arrondie au trait suivant)", "L'heure de départ que vous prévoyez", "L'heure d'arrivée augmentée de 2 heures"], a: 0, e: "On règle le disque sur l'heure d'arrivée (au trait qui suit). Le modifier sans partir est une fraude.", ref: "Art. 27.1" },
  { id: "st22", t: "stationnement", q: "Peut-on stationner sur un passage à niveau ou dans un tunnel ?", o: ["Non, l'arrêt même y est interdit", "Oui, en cas de bouchon", "Oui, avec les feux de détresse"], a: 0, e: "Arrêt et stationnement interdits sur les passages à niveau et dans les tunnels (sauf emplacements prévus), et partout où le véhicule constitue un danger ou une gêne.", ref: "Art. 24" },
  { id: "st23", t: "stationnement", q: "Votre véhicule stationné cache un panneau ou un feu aux autres usagers. Est-ce permis ?", o: ["Non", "Oui, si la place est marquée", "Oui, la nuit"], a: 0, e: "Il est interdit de s'arrêter ou de stationner à un endroit où le véhicule masque la signalisation aux autres usagers.", ref: "Art. 24" },
  { id: "st24", t: "stationnement", q: "Stationner sur un trottoir là où c'est autorisé par marquage : combien d'espace faut-il laisser aux piétons ?", o: ["Au moins 1,5 m", "50 cm", "Rien de particulier"], a: 0, fix: true, e: "Quand le stationnement partiellement ou totalement sur le trottoir est autorisé, il faut laisser au moins 1,5 m de passage libre aux piétons (poussettes, chaises roulantes).", ref: "Code de la route : stationnement sur trottoir" },

  /* =================== AUTOROUTE (suite) =================== */
  { id: "a11", t: "autoroute", q: "Sur autoroute, vous voulez passer de la bande de droite à la bande de gauche (3 bandes). Vous :", o: ["Changez une bande à la fois, en vérifiant à chaque fois", "Traversez les deux bandes d'un coup, avec le clignotant", "Klaxonnez, puis changez de bande sans attendre"], a: 0, e: "Changer de bande une à la fois, avec rétroviseurs, angle mort et clignotant à chaque fois.", ref: "Art. 12.4" },
  { id: "a12", t: "autoroute", q: "Quand commencez-vous à ralentir pour sortir de l'autoroute ?", o: ["Sur la bande de décélération", "Sur la bande de droite de l'autoroute, bien avant", "Au milieu de la bretelle"], a: 0, e: "On signale tôt avec le clignotant droit, on se met sur la bande de décélération, puis on ralentit dessus — pas sur l'autoroute, pour ne pas surprendre ceux qui suivent.", ref: "Conduite" },
  { id: "a13", t: "autoroute", q: "Vous êtes fatigué sur l'autoroute. La meilleure solution est :", o: ["M'arrêter sur une aire de repos et dormir 15-20 minutes", "Ouvrir la fenêtre et monter le son pour rester éveillé", "M'arrêter sur la bande d'arrêt d'urgence pour me reposer"], a: 0, e: "La seule solution contre la fatigue est le repos. La bande d'arrêt d'urgence n'est pas une aire de repos.", ref: "Sécurité" },
  { id: "a14", t: "autoroute", g: true, q: "Peut-on rouler sur la bande d'arrêt d'urgence pour éviter un bouchon jusqu'à la prochaine sortie ?", o: ["Non", "Oui si on roule lentement", "Oui avec les feux de détresse"], a: 0, e: "Circuler sur la bande d'arrêt d'urgence est interdit (sauf signal l'autorisant). Elle doit rester libre pour les secours.", ref: "Art. 21" },
  { id: "a15", t: "autoroute", q: "Peut-on s'arrêter sur la bande d'arrêt d'urgence pour passer un coup de téléphone ?", o: ["Non : seulement en cas de nécessité absolue", "Oui, c'est prévu pour s'arrêter en sécurité", "Oui, si l'arrêt dure moins de 5 minutes"], a: 0, e: "La bande d'arrêt d'urgence est réservée à la nécessité absolue (panne, malaise). Pour téléphoner : aire de repos ou kit mains libres.", ref: "Art. 21" },
  { id: "a16", t: "autoroute", q: "À la fin d'une bande d'accélération, il n'y a pas de créneau. Que faites-vous ?", o: ["Je ralentis, au besoin je m'arrête au bout et j'attends un créneau", "Je force le passage : ceux de l'autoroute doivent me laisser entrer", "Je continue sur la bande d'arrêt d'urgence jusqu'à trouver un trou"], a: 0, e: "Celui qui s'insère cède le passage. Mieux vaut attendre (rarement nécessaire) que forcer. Un regard tôt dans le rétroviseur aide à choisir son créneau.", ref: "Art. 12.4" },
  { id: "a17", t: "autoroute", q: "Y a-t-il des péages pour les voitures sur les autoroutes belges ?", o: ["Non (sauf quelques ouvrages, comme le Liefkenshoek)", "Oui, une vignette annuelle pour toutes les voitures", "Oui, un péage à chaque sortie d'autoroute"], a: 0, e: "Pas de péage autoroutier pour les voitures en Belgique. Seuls quelques ouvrages sont payants (tunnel du Liefkenshoek à Anvers). Les camions paient une redevance kilométrique.", ref: "Culture générale" },
  { id: "a18", t: "autoroute", q: "Une flèche oblique lumineuse au-dessus de votre bande vous indique :", o: ["De changer de bande dans la direction de la flèche", "Qu'une sortie est conseillée dans cette direction", "Que la vitesse est réduite sur cette bande"], a: 0, e: "Flèche oblique = la bande se ferme plus loin : rabattez-vous dans le sens indiqué. Croix rouge = bande fermée.", ref: "Signaux à message variable" },
  { id: "a19", t: "autoroute", q: "Un panneau F9 (route pour automobiles) : quelles interdictions sont communes avec l'autoroute ?", s: "F9", o: ["Demi-tour, marche arrière, arrêt hors endroits prévus, piétons", "Aucune : c'est une route ordinaire avec un panneau bleu", "Uniquement la limite de vitesse de 120 km/h"], a: 0, e: "Sur une route pour automobiles, les mêmes interdictions de circulation et de manœuvre que sur autoroute s'appliquent. La vitesse, elle, est celle de l'endroit.", ref: "Art. 22" },
  { id: "a20", t: "autoroute", g: true, q: "Une remorque est-elle autorisée à circuler sur l'autoroute derrière une voiture ?", o: ["Oui", "Non", "Seulement la nuit"], a: 0, e: "Oui, un ensemble voiture + remorque peut circuler sur autoroute s'il peut atteindre 70 km/h. Une voiture en panne, elle, doit être dépannée par un dépanneur agréé.", ref: "Art. 21" },

  /* =================== VULNÉRABLES (suite) =================== */
  { id: "u16", t: "vulnerables", q: "Un enfant roule au pas sur une trottinette non motorisée. Il est considéré comme :", o: ["Un piéton", "Un cycliste", "Un cyclomotoriste"], a: 0, e: "Les utilisateurs d'engins de déplacement non motorisés (trottinette, rollers, skate) qui se déplacent au pas sont considérés comme des piétons.", ref: "Code de la route : définitions" },
  { id: "u17", t: "vulnerables", q: "Un monoroue, un hoverboard ou une trottinette électrique sont des :", o: ["Engins de déplacement motorisés (EDP)", "Cyclomoteurs de classe A", "Jouets, sans règles particulières"], a: 0, e: "Ce sont des EDP : 25 km/h max, mêmes règles que les cyclistes, 16 ans minimum (sauf exceptions).", ref: "Art. 2.15.2" },
  { id: "u18", t: "vulnerables", q: "Une piste cyclable délimitée par deux lignes blanches discontinues est-elle obligatoire pour les cyclistes ?", o: ["Oui, dans leur sens, si elle est praticable", "Non, jamais : c'est seulement conseillé", "Seulement pour les enfants de moins de 10 ans"], a: 0, e: "Une piste cyclable (signalée par D7 ou marquée par deux lignes discontinues) doit être empruntée par les cyclistes dans le sens de leur marche, si elle est praticable. Le futur code (2027) assouplit cette obligation dans les zones à 50 km/h.", ref: "Art. 9.3" },
  { id: "u19", t: "vulnerables", q: "Hors agglomération, il n'y a ni trottoir ni accotement. De quel côté les piétons isolés doivent-ils marcher ?", o: ["À gauche, face aux véhicules", "À droite, dans le sens de la circulation", "Au milieu, pour être bien vus"], a: 0, e: "Sur la chaussée, les piétons isolés circulent en principe sur le côté gauche, pour voir arriver les véhicules en face (sauf danger).", ref: "Code de la route : piétons" },
  { id: "u20", t: "vulnerables", q: "Sur un passage pour cyclistes (damier), un cycliste est engagé. Vous :", o: ["Le laissez passer", "Passez avant lui", "Klaxonnez"], a: 0, e: "On s'approche d'un passage pour cyclistes à vitesse modérée et on laisse passer les cyclistes et cyclomotoristes qui y sont engagés.", ref: "Art. 40bis" },
  { id: "u21", t: "vulnerables", q: "Dans un embouteillage, un motard remonte entre les files. Est-ce permis ?", o: ["Oui, à 50 km/h max et 20 km/h de plus que les files", "Non, jamais : c'est un dépassement interdit", "Oui, sans limite de vitesse"], a: 0, e: "Les motards peuvent remonter entre les deux bandes les plus à gauche quand la circulation est lente, à 50 km/h maximum et avec une différence de 20 km/h maximum. Regardez vos rétroviseurs avant de changer de bande.", ref: "Code de la route (motos : remontée de files)" },
  { id: "u22", t: "vulnerables", q: "Une personne en chaise roulante se déplace sur la voie publique. Elle est considérée comme :", o: ["Un piéton", "Un cycliste", "Un véhicule lent"], a: 0, e: "Les personnes en fauteuil roulant (même électrique, au pas) sont assimilées aux piétons.", ref: "Code de la route : définitions" },
  { id: "u23", t: "vulnerables", q: "Deux personnes sur une trottinette électrique partagée. Est-ce permis ?", o: ["Non, pas de passager sur un EDP", "Oui si elles sont légères", "Oui pour un enfant"], a: 0, e: "Le transport de passagers sur une trottinette électrique est interdit.", ref: "Règles EDP" },
  { id: "u24", t: "vulnerables", q: "Un cycliste tend le bras gauche. Il signale :", o: ["Qu'il va tourner à gauche", "Qu'il vous dit de passer", "Qu'il va s'arrêter"], a: 0, e: "Les cyclistes signalent un changement de direction en tendant le bras du côté où ils vont tourner. Ralentissez et laissez-le se placer.", ref: "Art. 19.2" },
  { id: "u25", t: "vulnerables", q: "Une personne âgée commence à traverser lentement juste avant que votre feu passe au vert. Vous :", o: ["Attendez qu'elle ait fini de traverser", "Démarrez dès le vert, elle doit se presser", "Klaxonnez pour qu'elle termine plus vite"], a: 0, e: "Les piétons engagés sur un passage doivent pouvoir terminer leur traversée, même si votre feu passe au vert.", ref: "Art. 40" },
  { id: "u26", t: "vulnerables", q: "En agglomération, une voiture électrique roule très silencieusement. Quel risque particulier pour les piétons ?", o: ["Ils peuvent ne pas l'entendre arriver", "Aucun", "Ils vont l'entendre de loin"], a: 0, e: "À basse vitesse, les voitures électriques sont très silencieuses (un son artificiel AVAS est imposé sous ~20 km/h sur les modèles récents). Redoublez de prudence près des piétons, enfants et malvoyants.", ref: "Perception des risques" },
  { id: "u27", t: "vulnerables", g: true, q: "Un groupe d'enfants se trouve sur le trottoir près d'une école. Vous roulez en zone 30. Vous :", s: "A23", o: ["Ralentissez encore et êtes prêt à freiner", "Gardez 30 km/h, c'est la limite", "Klaxonnez pour les prévenir"], a: 0, e: "30 km/h est un maximum. Près d'enfants, anticipez un comportement imprévisible et soyez prêt à vous arrêter.", ref: "Art. 10 / A23" },
  { id: "u28", t: "vulnerables", q: "À partir de quel âge peut-on conduire un cyclomoteur classe B (45 km/h) avec le permis AM ?", o: ["16 ans", "14 ans", "18 ans"], a: 0, fix: true, e: "Le permis AM (cyclomoteurs classe A, B et speed pedelecs) est accessible dès 16 ans.", ref: "Permis AM" },

  /* =================== ALCOOL, DROGUES, GSM, FATIGUE (suite) =================== */
  { id: "al11", t: "alcool", q: "Un jeune conducteur qui vient d'avoir son permis B a-t-il un taux d'alcool maximal plus bas ?", o: ["Non : 0,5 g/l comme les autres (0,2 g/l pour les pros)", "Oui : tolérance zéro (0,0 g/l) pendant 2 ans", "Oui : 0,2 g/l pendant les 3 premières années"], a: 0, e: "En Belgique, il n'existe pas (actuellement) de taux spécifique pour les jeunes conducteurs : 0,5 g/l pour tous, sauf conducteurs professionnels (0,2 g/l). Mais le risque d'accident d'un jeune conducteur augmente plus vite avec l'alcool.", ref: "Loi du 16 mars 1968, art. 34" },
  { id: "al12", t: "alcool", q: "0,5 g/l d'alcool dans le sang correspond à combien dans l'air expiré ?", o: ["0,22 mg/l", "0,5 mg/l", "0,05 mg/l"], a: 0, fix: true, e: "0,5 g/l de sang = 0,22 mg/l d'air alvéolaire expiré (ce que mesure l'éthylomètre). 0,8 g/l = 0,35 mg/l.", ref: "Loi du 16 mars 1968" },
  { id: "al13", t: "alcool", q: "Quand l'éthylotest antidémarrage (alcolock) peut-il être imposé ?", o: ["Par le juge, notamment en cas de taux très élevé ou de récidive", "À tous les jeunes conducteurs pendant leurs 2 premières années", "Jamais : l'alcolock n'existe pas en Belgique"], a: 0, e: "Le juge peut (et dans certains cas doit, par exemple à partir de 1,8 g/l ou en récidive) imposer un permis limité aux véhicules équipés d'un alcolock, à charge du conducteur.", ref: "Loi du 16 mars 1968, art. 37/1" },
  { id: "al14", t: "alcool", q: "Vous avez beaucoup bu la veille au soir. Le lendemain matin à 8 h :", o: ["Il peut rester de l'alcool : attendez ou faites-vous conduire", "Une nuit de sommeil a éliminé tout l'alcool", "Un petit-déjeuner copieux suffit à faire baisser le taux"], a: 0, e: "L'alcool s'élimine lentement (≈ 0,1 à 0,15 g/l par heure). Après une grosse soirée, on peut encore être au-dessus de la limite le lendemain matin.", ref: "Sécurité routière" },
  { id: "al15", t: "alcool", q: "Le GPS de votre smartphone est fixé dans un support. Pouvez-vous le consulter en roulant ?", o: ["Oui, s'il est fixé et que vous ne le tenez pas en main", "Non, l'écran du téléphone ne peut jamais être regardé", "Oui, même en le tenant en main pour le GPS"], a: 0, e: "L'interdiction vise l'appareil tenu en main. Fixé dans un support, il peut servir de GPS, mais le programmer en roulant reste dangereux : faites-le avant de partir.", ref: "Art. 8.4" },
  { id: "al16", t: "alcool", q: "Fumer dans une voiture en présence d'un mineur :", o: ["Est interdit", "Est permis fenêtre ouverte", "Est permis si l'enfant est à l'arrière"], a: 0, e: "Il est interdit de fumer dans un véhicule en présence de passagers mineurs. Même fenêtre ouverte.", ref: "Loi 2019 (tabac)" },
  { id: "al17", t: "alcool", q: "À 90 km/h, un micro-sommeil de 3 secondes vous fait parcourir environ :", o: ["25 m", "75 m", "150 m"], a: 1, fix: true, e: "90 km/h = 25 m/s. 3 secondes les yeux fermés = 75 m sans contrôle du véhicule.", ref: "Fatigue" },
  { id: "al18", t: "alcool", q: "À quel moment le risque de s'endormir au volant est-il le plus élevé ?", o: ["La nuit entre 2 h et 5 h, et en début d'après-midi", "Le matin entre 8 h et 10 h, après le réveil", "En fin de journée, entre 17 h et 19 h"], a: 0, e: "Notre horloge biologique crée deux creux de vigilance : la nuit (2 h-5 h) et après le repas de midi (13 h-15 h).", ref: "Fatigue" },
  { id: "al19", t: "alcool", q: "Une boisson énergisante (caféine, taurine) permet-elle de conduire après avoir bu de l'alcool ?", o: ["Non : elle masque la fatigue, mais pas l'alcool", "Oui : la caféine accélère l'élimination de l'alcool", "Oui, si on en boit deux avant de partir"], a: 0, e: "Les boissons énergisantes donnent une fausse impression de vigilance. Le taux d'alcool et les réflexes ralentis restent les mêmes.", ref: "Sécurité routière" },
  { id: "al20", t: "alcool", q: "Le cannabis consommé la veille peut-il encore être détecté au contrôle salivaire ?", o: ["Oui, parfois longtemps après, et c'est sanctionné", "Non, après une heure il n'est plus détectable", "Seulement s'il a été fumé dans la voiture"], a: 0, e: "Les traces peuvent rester détectables longtemps selon la consommation. Avec la tolérance zéro, un test positif suffit à sanctionner.", ref: "Art. 37bis" },
  { id: "al21", t: "alcool", q: "Manger ou boire (non alcoolisé) en conduisant :", o: ["N'est pas interdit, mais vous devez garder le contrôle", "Est interdit et sanctionné de 191 €, comme le GSM en main", "Est permis seulement à l'arrêt, au feu rouge ou au bouchon"], a: 0, e: "Le conducteur doit toujours être en état de conduire et garder le contrôle du véhicule (art. 8.3). Une distraction qui fait perdre le contrôle peut être sanctionnée.", ref: "Art. 8.3" },
  { id: "al22", t: "alcool", q: "Vous êtes très énervé après une dispute. Quel est le bon réflexe avant de prendre le volant ?", o: ["Attendre de retrouver son calme", "Conduire vite pour se défouler", "Mettre la musique à fond"], a: 0, e: "Les émotions fortes (colère, stress, tristesse) réduisent l'attention et poussent à prendre des risques. Prenez le temps de vous calmer.", ref: "Aptitude à la conduite" },

  /* =================== CEINTURE & ENFANTS (suite) =================== */
  { id: "c8", t: "securite", q: "Un enfant peut-il voyager à l'avant de la voiture ?", o: ["Oui, dans un dispositif adapté (airbag coupé si dos à la route)", "Non, la loi belge l'interdit avant l'âge de 12 ans", "Oui, sur les genoux d'un adulte attaché à l'avant"], a: 0, e: "La loi belge n'interdit pas l'avant aux enfants, à condition d'utiliser le dispositif adapté. L'arrière reste plus sûr.", p: "« Pas d'enfant devant avant 10/12 ans » n'est pas une règle belge.", ref: "Art. 35.1.1" },
  { id: "c9", t: "securite", q: "Selon la norme i-Size (R129), un bébé doit voyager dos à la route au moins jusqu'à :", o: ["15 mois", "6 mois", "3 ans"], a: 0, fix: true, e: "La norme R129 impose le dos à la route au minimum jusqu'à 15 mois. Les spécialistes recommandent de le garder le plus longtemps possible (jusqu'à 4 ans si possible).", ref: "Règlement R129" },
  { id: "c10", t: "securite", q: "Comment une femme enceinte doit-elle porter la ceinture ?", o: ["Diagonale entre les seins, ventrale sous le ventre", "Sangle ventrale sur le ventre, bien serrée", "Elle est dispensée pendant toute la grossesse"], a: 0, e: "Ceinture obligatoire aussi pendant la grossesse (sauf dispense médicale) : sangle ventrale bien basse sous le ventre, sur les os du bassin.", ref: "Art. 35" },
  { id: "c11", t: "securite", q: "Un passager pose les pieds sur le tableau de bord. Quel est le risque ?", o: ["En cas de choc, l'airbag peut gravement blesser jambes et visage", "Aucun, l'airbag passager ne se déclenche qu'avec le pied au sol", "Il abîme le tableau de bord mais ne présente pas de danger"], a: 0, e: "L'airbag se déploie à plus de 200 km/h. Pieds sur le tableau de bord = genoux projetés vers le visage. Position correcte : dos contre le dossier, pieds au sol.", ref: "Sécurité passive" },
  { id: "c12", t: "securite", q: "Un sac lourd est posé non attaché sur la plage arrière. En cas de choc à 50 km/h :", o: ["Il devient un projectile très lourd lors du choc", "Il reste en place grâce à la plage arrière", "Aucun danger, s'il s'agit d'objets mous"], a: 0, e: "Lors d'un choc, un objet non arrimé est projeté avec une force énorme (une bouteille de 1 kg peut frapper comme plusieurs dizaines de kg). Rangez les objets lourds dans le coffre.", ref: "Sécurité passive" },
  { id: "c13", t: "securite", q: "Combien de passagers pouvez-vous transporter dans votre voiture ?", o: ["Pas plus que le nombre de places assises équipées", "Autant qu'on peut en faire entrer pour un court trajet", "Un enfant de plus par banquette arrière"], a: 0, e: "Chaque occupant doit disposer d'une place avec ceinture. Le nombre de places figure sur le certificat d'immatriculation.", ref: "Code de la route : passagers" },
  { id: "c14", t: "securite", q: "Un chien voyage dans la voiture. Comment le transporter ?", o: ["Attaché (harnais) ou en cage, sans gêner le conducteur", "Libre sur le siège passager, vitre entrouverte", "Sur les genoux d'un passager à l'avant"], a: 0, e: "Un animal ne peut pas gêner le conducteur ni entraver sa liberté de mouvement ou sa vue. Non attaché, il devient un projectile en cas de freinage.", ref: "Code de la route : comportement du conducteur" },
  { id: "c15", t: "securite", q: "Qui peut être dispensé du port de la ceinture ?", o: ["Une personne avec un certificat médical de dispense", "Les passagers arrière, sur un trajet court", "Les femmes enceintes, automatiquement"], a: 0, e: "Les dispenses sont rares : certificat médical, certaines activités professionnelles (livraisons de porte à porte en agglomération, services d'intervention…).", ref: "Art. 35.2" },

  /* =================== VÉHICULE & ÉCLAIRAGE (suite) =================== */
  { id: "e11", t: "vehicule", q: "Les feux de jour (DRL) suffisent-ils pour rouler la nuit ou dans un tunnel ?", o: ["Non : ils éclairent peu et l'arrière reste souvent éteint", "Oui, ils suffisent la nuit sur les routes bien éclairées", "Oui, en agglomération et dans les tunnels éclairés"], a: 0, e: "Les feux de jour servent à être vu de jour. La nuit, dans un tunnel ou par mauvaise visibilité, il faut allumer les feux de croisement (qui allument aussi les feux arrière).", ref: "Art. 30" },
  { id: "e12", t: "vehicule", q: "Les feux de brouillard AVANT peuvent être utilisés :", o: ["Par brouillard, neige ou forte pluie (visibilité réduite)", "La nuit, sur les routes de campagne non éclairées", "En ville, pour être plus visible des piétons et cyclistes"], a: 0, e: "Les feux de brouillard avant ne s'utilisent que lorsque le brouillard, la neige ou une pluie intense réduisent la visibilité. Le feu ARRIÈRE seulement si la visibilité est inférieure à 100 m.", ref: "Art. 30.3" },
  { id: "e13", t: "vehicule", q: "Dans le brouillard, pourquoi ne pas utiliser les feux de route ?", o: ["La lumière est renvoyée par le brouillard et éblouit", "Ils consomment trop d'énergie par temps froid", "Ils sont interdits par la loi en journée"], a: 0, e: "Les gouttelettes renvoient la lumière des feux de route : on voit encore moins bien (« mur blanc »). Feux de croisement + antibrouillards.", ref: "Art. 30" },
  { id: "e14", t: "vehicule", q: "Quand faut-il vérifier la pression des pneus ?", o: ["À froid, environ une fois par mois et avant un long trajet", "À chaud, juste après un long trajet sur autoroute", "Une fois par an, au contrôle technique"], a: 0, e: "La pression se mesure à froid. Pneus sous-gonflés : freinage plus long, risque d'éclatement, consommation plus élevée.", ref: "Entretien" },
  { id: "e15", t: "vehicule", q: "La pédale de frein devient molle et s'enfonce plus que d'habitude. Que faire ?", o: ["Faire vérifier les freins immédiatement (liquide, fuite)", "Continuer : c'est normal quand les freins chauffent", "Appuyer plus fort, puis faire vérifier à l'entretien annuel"], a: 0, e: "Une pédale molle signale souvent un problème de liquide de frein (fuite, air dans le circuit, liquide usé). Danger : faites contrôler sans attendre.", ref: "Entretien" },
  { id: "e16", t: "vehicule", g: true, q: "Il a neigé. Votre toit et votre pare-brise sont couverts de neige. Avant de partir :", o: ["Je dégage toutes les vitres, les feux, les plaques ET le toit", "Je dégage le pare-brise ; le reste partira en roulant", "Je dégage le pare-brise et la lunette arrière seulement"], a: 0, e: "Le conducteur doit avoir une visibilité suffisante (vitres dégagées) et ses feux/plaques doivent être visibles. La neige du toit peut glisser sur le pare-brise au freinage ou aveugler les suivants.", ref: "Code de la route : visibilité du conducteur" },
  { id: "e17", t: "vehicule", q: "Freinage d'urgence avec ABS : que faites-vous ?", o: ["J'appuie à fond et je maintiens, même si la pédale vibre", "Je pompe sur la pédale pour éviter le blocage", "Je freine doucement pour ne pas bloquer les roues"], a: 0, e: "Avec l'ABS, on freine à fond et on maintient la pression (avec débrayage en boîte manuelle). Les vibrations sont normales. Les roues ne bloquent pas : on garde la possibilité de diriger.", ref: "Technique" },
  { id: "e18", t: "vehicule", q: "Quel est le rôle de l'ESP (contrôle électronique de stabilité) ?", o: ["Corriger les débuts de dérapage en freinant certaines roues", "Augmenter la puissance du moteur dans les fortes côtes", "Remplacer les pneus hiver quand il fait très froid"], a: 0, e: "L'ESP aide à garder la trajectoire en cas de perte d'adhérence. Il ne fait pas de miracle si la vitesse est trop élevée.", ref: "Technique" },
  { id: "e19", t: "vehicule", q: "Un témoin ORANGE (ex. moteur, pression des pneus) s'allume. Signification ?", o: ["Anomalie à faire vérifier rapidement, sans arrêt immédiat", "Danger immédiat : arrêt obligatoire sur-le-champ", "Simple information : tout fonctionne normalement"], a: 0, e: "Code couleur : rouge = danger, arrêt dès que possible ; orange = anomalie à contrôler bientôt ; vert/bleu = information (feux allumés…).", ref: "Connaissance du véhicule" },
  { id: "e20", t: "vehicule", q: "Comment contrôler le niveau d'huile moteur correctement ?", o: ["À plat, moteur arrêté depuis quelques minutes, à la jauge", "Moteur en marche, pour que l'huile circule bien", "Juste après un long trajet, quand le moteur est chaud"], a: 0, e: "Contrôle sur sol plat, moteur arrêté (quelques minutes pour que l'huile redescende). Manque d'huile = risque de casse moteur.", ref: "Entretien" },
  { id: "e21", t: "vehicule", q: "En entrant dans un tunnel, vous devez :", o: ["Allumer les feux de croisement et respecter les distances", "Allumer les feux de détresse pendant la traversée", "Allumer les feux de route pour mieux voir les parois"], a: 0, e: "Dans un tunnel : feux de croisement, pas de demi-tour, pas de marche arrière, pas d'arrêt hors nécessité, respect des distances et des signaux.", ref: "Art. 30 / 24" },
  { id: "e22", t: "vehicule", q: "Avec une voiture très chargée (coffre plein, 5 passagers), il faut adapter :", o: ["Le réglage des phares et la pression des pneus", "Rien, la voiture est prévue pour sa charge", "Seulement la position du rétroviseur intérieur"], a: 0, e: "Une voiture chargée « lève le nez » : sans correction, les phares éblouissent ceux d'en face. La pression des pneus doit aussi être adaptée (voir étiquette dans la portière).", ref: "Entretien" },
  { id: "e23", t: "vehicule", q: "Les plaques d'immatriculation doivent être :", o: ["Lisibles, propres et éclairées la nuit (plaque arrière)", "Obligatoires à l'arrière, facultatives à l'avant", "Personnalisables librement (couleur, police)"], a: 0, e: "Plaques avant et arrière lisibles ; la plaque arrière doit être éclairée la nuit. Une plaque illisible (boue, neige, porte-vélos) est sanctionnable.", ref: "AR immatriculation" },
  { id: "e24", t: "vehicule", q: "Le rétroviseur extérieur ne montre pas une zone appelée « angle mort ». Comment la contrôler ?", o: ["En tournant la tête (coup d'œil par-dessus l'épaule)", "En regardant deux fois dans le rétroviseur", "En klaxonnant"], a: 0, e: "Un bref regard par-dessus l'épaule avant tout déplacement latéral (changement de bande, démarrage, tourner à droite près des cyclistes).", ref: "Technique" },
  { id: "e25", t: "vehicule", q: "Les pneus été perdent fortement en adhérence en dessous de :", o: ["Environ 7 °C", "0 °C", "15 °C"], a: 0, fix: true, e: "Sous ~7 °C, la gomme des pneus été durcit. Les pneus hiver (ou 4 saisons) gardent leur adhérence par temps froid, même sur route sèche.", ref: "Équipement" },

  /* =================== PANNE, ACCIDENT & SECOURS (suite) =================== */
  { id: "ac10", t: "accident", q: "De la fumée sort du capot de votre voiture. Que faites-vous ?", o: ["Arrêt, contact coupé, tout le monde dehors, capot à peine ouvert", "J'ouvre grand le capot pour voir d'où vient la fumée", "Je continue doucement jusqu'au garage le plus proche"], a: 0, e: "Ouvrir grand le capot apporte de l'oxygène au feu. Évacuez, éloignez-vous, appelez le 112, utilisez l'extincteur par l'entrebâillement si c'est sans risque.", ref: "Premiers secours" },
  { id: "ac11", t: "accident", q: "Une victime saigne abondamment du bras. Que faites-vous ?", o: ["Je comprime directement la plaie et j'appelle le 112", "Je lui donne à boire et je l'assieds", "Je lui fais un garrot serré au-dessus du coude"], a: 0, e: "Hémorragie : compression directe et ferme de la plaie, allonger la victime, appeler le 112. Ne pas donner à boire.", ref: "Premiers secours" },
  { id: "ac12", t: "accident", q: "Une victime ne respire pas. Que faites-vous après avoir appelé le 112 ?", o: ["Massage cardiaque et défibrillateur (DEA) dès que possible", "Position latérale de sécurité en attendant les secours", "Je lui surélève les jambes et j'attends les secours"], a: 0, e: "Arrêt cardiaque : chaque minute compte. Compressions thoraciques fortes et rapides (100-120/min, au centre de la poitrine) et DEA dès qu'il arrive : il guide vocalement.", ref: "Premiers secours" },
  { id: "ac13", t: "accident", q: "Un blessé conscient a soif et vous demande de l'eau. Vous :", o: ["Ne lui donnez rien à boire ni à manger", "Donnez-lui un peu d'eau pour le réconforter", "Donnez-lui un remontant (sucre, café)"], a: 0, e: "Une victime peut avoir besoin d'une opération (anesthésie) : rien à boire ni à manger. Humidifiez éventuellement les lèvres.", ref: "Premiers secours" },
  { id: "ac14", t: "accident", q: "Vous heurtez un sanglier sur une route de campagne. Que faites-vous ?", o: ["Je sécurise et j'avertis la police, sans toucher l'animal", "Je repars : un accident avec un animal n'est pas à déclarer", "J'emporte l'animal pour le déposer chez un vétérinaire"], a: 0, e: "Collision avec du gibier : sécuriser (feux de détresse, gilet, triangle), prévenir la police. Ne pas s'approcher d'un animal blessé (danger).", ref: "Accident" },
  { id: "ac15", t: "accident", q: "Vous accrochez une voiture stationnée dont le propriétaire est absent. Vous :", o: ["Je laisse mes coordonnées visibles et/ou je préviens la police", "Je pars : sans témoin, il n'y a pas d'obligation", "J'attends 5 minutes puis je pars si personne ne vient"], a: 0, e: "Partir sans permettre l'identification est un délit de fuite. Laissez un mot avec vos coordonnées (et prévenez la police si nécessaire).", ref: "Loi du 16 mars 1968, art. 33" },
  { id: "ac16", t: "accident", q: "Vous passez devant un accident où personne ne s'est encore arrêté et il y a des blessés. Êtes-vous obligé d'agir ?", o: ["Oui : la non-assistance est punissable (au minimum, alerter)", "Non, seuls les conducteurs impliqués doivent agir", "Seulement si je suis médecin ou secouriste"], a: 0, e: "Toute personne doit porter secours ou au moins appeler les secours, sans se mettre en danger.", ref: "Code pénal, art. 422bis" },
  { id: "ac17", t: "accident", q: "Un incendie se déclare dans un tunnel. Que faites-vous ?", o: ["Je m'arrête, laisse la clé et rejoins à pied l'issue de secours", "Je fais demi-tour pour ressortir par l'entrée du tunnel", "Je reste dans la voiture, vitres fermées, en attendant"], a: 0, e: "Dans un tunnel en feu, la fumée tue en quelques minutes. Laissez la clé (pour que les secours déplacent la voiture), évacuez à pied par les issues signalées (panneaux verts).", ref: "Sécurité tunnels" },
  { id: "ac18", t: "accident", q: "Lors d'un appel au 112, quelles informations sont essentielles ?", o: ["Où, quoi, combien de victimes et leur état", "Les marques, modèles et plaques des voitures", "Les noms des conducteurs et leurs assurances"], a: 0, e: "Donnez le lieu précis (route, sens, borne kilométrique, repères), la nature de l'accident, le nombre de victimes et leur état. Ne raccrochez pas en premier.", ref: "Secours" },
  { id: "ac19", t: "accident", q: "Sur le constat européen d'accident, les deux conducteurs :", o: ["Remplissent un seul formulaire, cochent, dessinent et signent", "Remplissent chacun un formulaire séparé, sans se concerter", "Remplissent le formulaire mais ne le signent pas"], a: 0, e: "Un constat commun : identités, assurances, circonstances (cases), croquis, signatures. Chacun garde un exemplaire. Après signature, on ne modifie plus le recto.", ref: "Assurance" },

  /* =================== CONDUITE & ANTICIPATION (suite) =================== */
  { id: "k14", t: "conduite", q: "Une voiture garée a les roues avant braquées vers la chaussée et une personne au volant. Vous anticipez :", o: ["Qu'elle va démarrer et s'insérer", "Qu'elle est garée pour longtemps", "Qu'elle va reculer vers vous"], a: 0, e: "Roues braquées + conducteur à bord = démarrage probable, parfois sans regarder. Ralentissez et préparez-vous.", ref: "Perception des risques" },
  { id: "k15", t: "conduite", q: "Vous approchez d'un passage pour piétons masqué par un camion arrêté sur la bande de droite. Vous :", o: ["Ralentissez fortement : un piéton peut surgir", "Accélérez pour passer avant qu'il ne redémarre", "Klaxonnez pour signaler votre présence"], a: 0, e: "Un véhicule qui masque un passage pour piétons cache peut-être un piéton. Il est d'ailleurs interdit de dépasser un véhicule arrêté devant un passage.", ref: "Perception des risques" },
  { id: "k16", t: "conduite", q: "Il gèle légèrement. Où le verglas est-il le plus probable ?", o: ["Sur les ponts, à l'ombre et en forêt", "En plein soleil, sur l'asphalte sombre", "Dans les tunnels, à cause de l'humidité"], a: 0, e: "Les ponts se refroidissent par-dessous et par-dessus ; les zones d'ombre ne dégèlent pas. Prudence dès que la température approche 3 °C.", ref: "Conduite hivernale" },
  { id: "k17", t: "conduite", q: "Sur route verglacée, la voiture commence à glisser. Le bon réflexe :", o: ["Lâcher l'accélérateur, regarder où on veut aller, douceur", "Freiner à fond pour bloquer les roues", "Donner un grand coup de volant dans l'autre sens"], a: 0, e: "Sur glace, tout geste brusque aggrave la glissade. Regardez et dirigez le volant vers où vous voulez aller.", ref: "Conduite hivernale" },
  { id: "k18", t: "conduite", q: "Un camion devant vous met son clignotant à droite mais se déporte d'abord vers la gauche avant un carrefour. Pourquoi ?", o: ["Il prend de l'élan pour tourner à droite : pas à sa droite !", "Il va finalement tourner à gauche au carrefour", "Il s'est trompé de direction et va corriger sa trajectoire"], a: 0, e: "Les véhicules longs prennent de l'élan vers la gauche pour tourner à droite. Se faufiler à droite = risque d'écrasement.", ref: "Perception des risques" },
  { id: "k19", t: "conduite", q: "Une voiture devant vous roule de façon hésitante, ralentit sans raison devant chaque rue. Vous anticipez :", o: ["Un conducteur perdu, qui peut tourner ou s'arrêter net", "Un conducteur prudent, sans risque particulier pour vous", "Un conducteur qui va accélérer pour dépasser"], a: 0, e: "Comportement hésitant (touriste, livreur qui cherche une adresse) = changement de direction soudain possible. Gardez vos distances.", ref: "Perception des risques" },
  { id: "k20", t: "conduite", q: "Le soleil bas vous éblouit de face. Vous :", o: ["Baisser le pare-soleil, ralentir, augmenter les distances", "Garder sa vitesse en suivant les feux de devant", "Fermer les yeux un instant pour ne pas être ébloui"], a: 0, e: "Un soleil rasant aveugle aussi les autres usagers (ils peuvent ne pas vous voir). Pare-brise propre, lunettes de soleil, vitesse réduite.", ref: "Conduite" },
  { id: "k21", t: "conduite", q: "Le principe de « regarder loin » en conduisant sert à :", o: ["Repérer les dangers plus tôt et avoir le temps de réagir", "Éviter de regarder trop souvent dans les rétroviseurs", "Pouvoir rouler plus vite en sécurité"], a: 0, e: "Regarder loin (12-15 secondes devant) permet d'anticiper. On alterne avec les rétroviseurs (toutes les 5-8 s) et les côtés.", ref: "Conduite défensive" },
  { id: "k22", t: "conduite", q: "Un vent latéral fort souffle sur un viaduc. Un camion vous dépasse. À quoi vous attendre ?", o: ["À un déport quand le camion vous abrite puis vous découvre", "À rien : le camion vous protège du vent latéral", "À une forte aspiration qui fait accélérer votre voiture"], a: 0, e: "Le camion vous protège du vent puis vous l'expose brutalement : tenez fermement le volant et anticipez la correction.", ref: "Perception des risques" },
  { id: "k23", t: "conduite", q: "Avant de démarrer, l'ordre logique d'installation est :", o: ["Siège, appui-tête, rétroviseurs, ceinture", "Ceinture, puis rétroviseurs en roulant", "Radio, GPS, siège"], a: 0, e: "On règle d'abord le siège (distance pédales/volant), puis l'appui-tête, les rétroviseurs, et on attache la ceinture. Tout cela avant de démarrer.", ref: "Installation" },
  { id: "k24", t: "conduite", q: "Comment tenir le volant correctement ?", o: ["Les deux mains, position « 9 h 15 »", "Une main en haut", "Les mains croisées à 12 h"], a: 0, e: "Mains à 9 h 15 : meilleure précision, pas d'interférence avec l'airbag, réaction rapide.", ref: "Technique" },
  { id: "k25", t: "conduite", q: "Une feuille mouillée en automne ou des feuilles mortes sur la route :", o: ["Rendent la chaussée glissante", "N'ont aucun effet", "Améliorent l'adhérence"], a: 0, e: "Feuilles mortes humides = adhérence comparable à une route verglacée par endroits. Freinage doux et anticipé.", ref: "Conduite" },
  { id: "k26", t: "conduite", q: "Un ballon traverse devant vous à la sortie d'une école. Vous avez freiné à temps. Que faites-vous ensuite ?", o: ["Je reste à l'arrêt ou repars très lentement", "Je repars aussitôt, le ballon est passé", "Je klaxonne pour prévenir les enfants"], a: 0, e: "Le danger principal n'est pas le ballon mais l'enfant qui court derrière, souvent sans regarder.", ref: "Perception des risques" },
  { id: "k27", t: "conduite", q: "La règle des 2 secondes : à 90 km/h, cela correspond à environ :", o: ["50 m", "20 m", "100 m"], a: 0, fix: true, e: "90 km/h = 25 m/s. 2 secondes = 50 m. Repère pratique : sur autoroute, l'espace entre deux balises est souvent de 50 m (une balise d'écart minimum).", ref: "Art. 18" },
  { id: "k28", t: "conduite", q: "Vous roulez de nuit sur une route de campagne. Un panneau A29 (animaux sauvages) est placé. Que faites-vous ?", o: ["Je ralentis et je surveille les bas-côtés", "J'accélère pour passer vite la zone boisée", "J'allume les feux de détresse dans la zone"], a: 0, e: "Aube et crépuscule sont les moments à risque. Si un animal traverse, d'autres peuvent suivre. Freinez en ligne droite plutôt que de faire un écart dangereux.", ref: "Perception des risques" },
  { id: "k29", t: "conduite", q: "Un animal surgit devant vous à 80 km/h, une voiture arrive en face. Le plus sûr est généralement :", o: ["Freiner fort en gardant la trajectoire", "Donner un coup de volant vers la gauche", "Donner un coup de volant vers le fossé"], a: 0, e: "Les écarts brusques causent souvent des accidents plus graves (sortie de route, choc frontal) que la collision avec un petit/moyen animal.", ref: "Conduite défensive" },
  { id: "k30", t: "conduite", q: "Le freinage moteur consiste à :", o: ["Lever le pied en restant embrayé, voire rétrograder", "Couper le moteur en roulant pour économiser le carburant", "Mettre au point mort pour profiter de l'élan en descente"], a: 0, e: "Le frein moteur ralentit sans user les freins et sans consommer (injection coupée). En longue descente, il évite la surchauffe des freins. Jamais au point mort en descente.", ref: "Technique / éco-conduite" },
  { id: "k31", t: "conduite", q: "Sur une route à plusieurs bandes, une voiture double sans cesse en zigzaguant. Que faites-vous ?", o: ["Je garde mon calme, ma bande et mes distances", "Je l'empêche de passer pour lui donner une leçon", "Je le suis de près pour relever sa plaque"], a: 0, e: "Ne vous laissez pas entraîner dans un conflit. La conduite défensive, c'est aussi laisser de la marge aux conducteurs dangereux.", ref: "Conduite défensive" },
  { id: "k32", t: "conduite", q: "Le principe de confiance : peut-on toujours compter sur le fait que les autres respectent les règles ?", o: ["En principe oui, sauf si des indices montrent le contraire", "Oui, toujours : chacun respecte le code", "Non, jamais : il faut toujours s'attendre au pire"], a: 0, e: "On peut compter sur le respect des règles par les autres, mais pas aveuglément : face à un enfant, un usager distrait ou une situation suspecte, il faut anticiper l'erreur.", ref: "Conduite défensive" },
  { id: "k33", t: "conduite", q: "Une voiture devant vous freine brusquement, l'espace est trop court. La meilleure prévention était :", o: ["Garder une distance de sécurité suffisante (2 s minimum)", "Avoir des freins récents et bien entretenus", "Rouler plus près pour mieux voir ses feux stop"], a: 0, e: "La plupart des collisions par l'arrière viennent d'une distance trop courte. Deux secondes, c'est le temps de réagir (1 s) plus une marge.", ref: "Art. 18" },
  { id: "k34", t: "conduite", q: "Vous avez un doute sur une situation (priorité incertaine, piéton hésitant). Le bon principe :", o: ["Dans le doute, je ralentis et je cède", "Dans le doute, je passe vite", "Je klaxonne et je passe"], a: 0, e: "Mieux vaut perdre quelques secondes qu'avoir un accident. À l'examen pratique aussi, l'hésitation prudente vaut mieux que le passage en force.", ref: "Conduite défensive" },

  /* =================== PERMIS, DOCUMENTS & SANCTIONS (suite) =================== */
  { id: "pm11", t: "permis", q: "Quel est l'âge minimum pour obtenir le permis B définitif ?", o: ["18 ans", "17 ans", "16 ans"], a: 0, fix: true, e: "Permis B définitif : 18 ans. On peut commencer la formation (examen théorique, permis provisoire) dès 17 ans.", ref: "AR 23/03/1998" },
  { id: "pm12", t: "permis", q: "Le permis B vous autorise à conduire :", o: ["Une voiture de 3 500 kg max, 8 passagers max + conducteur", "Un minibus de 15 places, pour un usage privé uniquement", "Un camion de 7,5 t, à condition de ne pas avoir de passagers"], a: 0, e: "Permis B : véhicules dont la masse maximale autorisée ne dépasse pas 3 500 kg, et conçus pour 8 passagers au maximum (+ conducteur). Il permet aussi les cyclomoteurs.", ref: "Directive 2006/126" },
  { id: "pm13", t: "permis", q: "Avec un permis B depuis au moins 2 ans, peut-on conduire une moto de 125 cm³ en Belgique ?", o: ["Oui, après une formation de 4 heures", "Oui, sans formation supplémentaire", "Non, il faut toujours le permis A1"], a: 0, e: "Avec un permis B depuis au moins 2 ans et une formation de 4 heures en école de conduite, on peut conduire une moto de 125 cm³ (catégorie A1) en Belgique.", ref: "AR permis A1" },
  { id: "pm14", t: "permis", q: "Pour être guide d'un candidat en filière libre, il faut notamment :", o: ["Permis B depuis 8 ans, pas de déchéance depuis 3 ans", "Permis B depuis 1 an, sans autre condition", "Être moniteur agréé dans une école de conduite"], a: 0, e: "Le guide doit être titulaire du permis B depuis au moins 8 ans, ne pas avoir été déchu du droit de conduire dans les 3 ans précédents, et être inscrit sur le permis provisoire.", ref: "AR 23/03/1998" },
  { id: "pm15", t: "permis", r: ["F"], q: "En Flandre, que doit faire un nouveau conducteur entre 6 et 9 mois après avoir obtenu son permis B ?", o: ["Participer au « terugkommoment » de formation", "Repasser l'examen pratique pour confirmer", "Rien, le permis est définitif"], a: 0, e: "En Flandre, le « terugkommoment » est une formation obligatoire de quelques heures (perception des risques, sécurité) à suivre entre 6 et 9 mois après l'obtention du permis.", ref: "Réglementation flamande" },
  { id: "pm16", t: "permis", q: "En Belgique, la plaque d'immatriculation :", o: ["Appartient au titulaire et le suit d'une voiture à l'autre", "Appartient à la voiture et reste avec elle à la revente", "Change à chaque passage au contrôle technique"], a: 0, e: "La plaque belge est personnelle : elle suit le titulaire d'un véhicule à l'autre (sauf demande de nouvelle plaque).", ref: "DIV" },
  { id: "pm17", t: "permis", q: "Quelles villes belges ont une zone de basses émissions (LEZ) en vigueur pour les voitures ?", o: ["Bruxelles, Anvers et Gand", "Toutes les communes", "Aucune"], a: 0, e: "Les LEZ de la Région bruxelloise, d'Anvers et de Gand interdisent l'accès aux véhicules trop polluants (selon la norme Euro et le carburant). Les conditions évoluent : vérifiez avant de rouler.", ref: "LEZ" },
  { id: "pm18", t: "permis", q: "Le tribunal de police peut prononcer une déchéance du droit de conduire. Cela signifie :", o: ["L'interdiction de conduire pendant une durée fixée", "Une simple amende, sans aucun effet sur le permis", "Un avertissement inscrit au casier judiciaire"], a: 0, e: "La déchéance retire le droit de conduire (de 8 jours à plusieurs années, voire définitivement). Le juge peut imposer de repasser les examens théorique, pratique, médical et/ou psychologique.", ref: "Loi du 16 mars 1968, art. 38" },
  { id: "pm19", t: "permis", q: "Un candidat au permis provisoire commet une infraction grave. Que prévoit la réforme de 2026 ?", o: ["Un réexamen obligatoire, comme pour les novices", "Rien de plus que l'amende habituelle", "Un retrait définitif et automatique du permis"], a: 0, e: "Depuis 2026, une infraction grave avec un permis provisoire peut entraîner l'obligation de repasser des examens, comme c'est déjà le cas pour les conducteurs novices.", ref: "Réforme 2026" },
  { id: "pm20", t: "permis", q: "Vous perdez votre permis de conduire. Que faites-vous ?", o: ["Je déclare la perte et je demande un duplicata", "Je continue à conduire, la police a mes données", "J'attends qu'on me le renvoie par la poste"], a: 0, e: "Signalez la perte ou le vol, puis demandez un duplicata à la commune. Vous devez pouvoir présenter votre permis lors d'un contrôle.", ref: "AR 23/03/1998" },
  { id: "pm21", t: "permis", q: "Quel est le barème des perceptions immédiates par degré d'infraction depuis le 1er juillet 2026 ?", o: ["64 € / 128 € / 191 € / 520 €", "58 € / 116 € / 174 € / 430 €", "50 € / 100 € / 150 € / 300 €"], a: 0, fix: true, e: "Après l'indexation de 10 % du 1er juillet 2026 : 1er degré 64 €, 2e degré 128 €, 3e degré 191 € (ex. GSM en main), 4e degré 520 €.", ref: "police.be, juillet 2026" },
  { id: "pm22", t: "permis", q: "À l'examen théorique, vous avez fait 1 faute grave et 4 erreurs légères. Résultat ?", o: ["41/50 : réussi, de justesse", "45/50 : réussi", "Échec"], a: 0, fix: true, e: "50 − 5 (grave) − 4 (légères) = 41/50 : c'est exactement le minimum. Une erreur de plus et c'est l'échec.", ref: "Barème de l'examen" },
  { id: "pm23", t: "permis", q: "Depuis le 1er janvier 2026, en Région bruxelloise, la formation aux premiers secours pour les candidats au permis B :", o: ["N'est plus obligatoire", "Est devenue obligatoire", "Dure 2 jours"], a: 0, e: "La Région de Bruxelles-Capitale a supprimé l'obligation de formation aux premiers secours pour les candidats au permis B (elle reste très utile !).", ref: "Réforme bruxelloise 2026" },

  /* =================== CHARGEMENT, REMORQUE & PASSAGERS =================== */
  { id: "ch1", t: "chargement", q: "Avec un permis B, quelle remorque pouvez-vous tracter sans condition supplémentaire ?", o: ["Une remorque de 750 kg de MMA maximum", "Une remorque de 3 500 kg de MMA maximum", "Aucune remorque sans permis BE"], a: 0, e: "Permis B : remorque jusqu'à 750 kg de MMA. Au-delà, c'est possible si la MMA totale de l'ensemble ne dépasse pas 3 500 kg. Au-delà encore : code B96 (jusqu'à 4 250 kg, après formation) ou permis BE.", ref: "Directive 2006/126" },
  { id: "ch2", t: "chargement", q: "Votre voiture a une MMA de 1 800 kg. Pouvez-vous tracter avec un permis B une remorque de 1 500 kg de MMA ?", o: ["Oui : l'ensemble fait 3 300 kg, moins de 3 500 kg", "Non : toute remorque de plus de 750 kg exige le BE", "Oui, quelle que soit la masse de l'ensemble"], a: 0, e: "Une remorque de plus de 750 kg est permise avec le B si la MMA voiture + remorque ne dépasse pas 3 500 kg (et dans la limite de la masse remorquable du véhicule).", ref: "Directive 2006/126" },
  { id: "ch3", t: "chargement", q: "Que permet la mention « B96 » sur le permis ?", o: ["Tracter un ensemble jusqu'à 4 250 kg, après formation", "Conduire un minibus jusqu'à 16 places assises", "Conduire une moto de 125 cm³ sans examen"], a: 0, e: "Le code 96 permet un ensemble de plus de 3 500 kg et jusqu'à 4 250 kg (remorque > 750 kg), après une formation spécifique.", ref: "Directive 2006/126" },
  { id: "ch4", t: "chargement", q: "Votre porte-vélos arrière cache la plaque d'immatriculation. Que faut-il ?", o: ["Une plaque supplémentaire officielle sur le porte-vélos", "Rien, si le trajet ne dépasse pas quelques kilomètres", "Un carton avec le numéro écrit à la main, bien visible"], a: 0, e: "La plaque doit rester visible : il faut une plaque supplémentaire (commandée auprès de la DIV) sur le porte-vélos, et les feux du porte-vélos s'ils masquent ceux de la voiture.", ref: "AR immatriculation" },
  { id: "ch5", t: "chargement", q: "Un chargement dépasse nettement à l'arrière de votre véhicule. Que devez-vous faire ?", o: ["Le signaler (dispositif rouge et blanc ; la nuit, un feu rouge)", "Rien, si le chargement est bien attaché", "Allumer les feux de détresse pendant tout le trajet"], a: 0, e: "Un chargement qui dépasse de plus d'un mètre à l'arrière doit être signalé (panneau rouge et blanc réfléchissant, et la nuit un feu rouge et un catadioptre).", ref: "Code de la route : chargement" },
  { id: "ch6", t: "chargement", q: "Le chargement d'un véhicule doit être :", o: ["Arrimé pour ne pas tomber, glisser ni gêner la vue", "Simplement posé si le trajet est court", "Couvert d'une bâche, sans autre obligation"], a: 0, e: "Le chargement doit être arrimé et ne pas compromettre la stabilité, masquer les feux/plaques, ni gêner la visibilité du conducteur.", ref: "Code de la route : chargement" },
  { id: "ch7", t: "chargement", q: "Un coffre de toit chargé modifie le comportement du véhicule :", o: ["Centre de gravité plus haut, prise au vent, consommation", "Aucun changement tant que la charge est légale", "Il améliore la tenue de route en virage"], a: 0, e: "Respectez la charge maximale du toit (notice), réduisez la vitesse par vent latéral et attention à la hauteur (parkings, C29). Retirez-le quand il est vide.", ref: "Conduite" },
  { id: "ch8", t: "chargement", q: "Une caravane gêne votre vue vers l'arrière. Que devez-vous faire ?", o: ["Installer des rétroviseurs supplémentaires", "Rien, la caméra de recul suffit", "Rouler avec les fenêtres ouvertes pour écouter"], a: 0, e: "Le conducteur doit voir vers l'arrière : avec une caravane large, des rétroviseurs extérieurs supplémentaires sont obligatoires.", ref: "Règlement technique" },
  { id: "ch9", t: "chargement", q: "Peut-on transporter des personnes dans une remorque ou une caravane en roulant ?", o: ["Non", "Oui pour les enfants", "Oui sur une courte distance"], a: 0, e: "Il est interdit de transporter des personnes dans une remorque ou une caravane en circulation.", ref: "Code de la route : transport de personnes" },
  { id: "ch10", t: "chargement", q: "Avec une remorque, votre distance de freinage :", o: ["S'allonge : plus de place pour freiner, dépasser et tourner", "Raccourcit grâce au poids supplémentaire", "Ne change pas si la remorque a ses propres freins"], a: 0, e: "Ensemble plus lourd et plus long : freinage plus long, dépassement plus long, virages plus larges, sensibilité au vent latéral.", ref: "Conduite" },
  { id: "ch11", t: "chargement", q: "Une remorque de plus de 750 kg de MMA doit en principe être équipée :", o: ["D'un système de freinage propre", "De rien de particulier", "D'un gyrophare"], a: 0, e: "Au-delà de 750 kg de MMA, la remorque doit avoir son propre système de freinage (et un câble de rupture).", ref: "Règlement technique" },
  { id: "ch12", t: "chargement", q: "Avant de partir avec une remorque, vous vérifiez notamment :", o: ["Attelage, prise et feux, câble de sécurité, pneus, charge", "Seulement que la plaque de la remorque soit lisible", "Rien de spécial si la remorque est neuve"], a: 0, e: "Check-list : attelage enclenché, câble de sécurité attaché, feux (stop, clignotants) testés, plaque, pneus, charge répartie (plus lourd au-dessus de l'essieu, poids sur la boule respecté).", ref: "Bonne pratique" }
);
